(window.GGReadingsData = window.GGReadingsData || {})["gceltx"] = [{"id":"celtx-cg-god-be-with-us","title":"God Be With Us","by":"Traditional (Scottish Gaelic)","tr":"Alexander Carmichael","year":1900,"trad":["celtic","christian"],"denom":["scottish"],"type":"litany","occasion":["daily","forgiveness","evening"],"text":"God be with us\nOn this Thy day,\nAmen.\n\nGod be with us\nOn this Thy night,\nAmen.\n\nTo us and with us,\nOn this Thy day,\nAmen.\n\nTo us and with us,\nOn this Thy night,\nAmen.\n\nIt is clear to be seen of us,\nSince we came into the world,\nThat we have deserved Thy wrath,\nAmen.\n\nO Thine own wrath,\nThou God of all,\nAmen.\n\nGrant us forgiveness,\nAmen.\nGrant us forgiveness,\nAmen.\n\nGrant to us Thine own forgiveness,\nThou merciful God of all,\nAmen.\n\nAnything that is evil to us,\nOr that may witness against us\nWhere we shall longest be,\nIllume it to us,\nObscure it to us,\nBanish it from us,\nRoot it out of our hearts,\nEver, evermore, everlastingly,\nEver, evermore, everlastingly.","note":"A call and answer prayer for the day and the night, each line answered with Amen.","voice":"brian","source":{"name":"Carmina Gadelica, vol. 1, Alexander Carmichael (1900)","url":"https://archive.org/details/carminagadelicah01carm_0/page/15/mode/1up"},"rights":"pd","pd":"published 1900; Carmichael died 1912"},{"id":"celtx-cg-cross-of-saints","title":"The Cross of the Saints and the Angels","by":"Traditional (Scottish Gaelic)","tr":"Alexander Carmichael","year":1900,"trad":["celtic","christian"],"denom":["scottish"],"type":"prayer","occasion":["evening","peace"],"text":"The cross of the saints and of the angels with me\nFrom the top of my face to the edge of my soles.\nO Michael mild, O Mary of glory,\nO gentle Bride of the locks of gold,\nPreserve Ye me in the weakly body,\nThe Three preserve me on the just path.\n\nOh! Three preserve me on the just path.\nPreserve Ye me in the soul-shrine poor,\nPreserve Ye me, and I so weak and naked,\nPreserve Ye me without offence on the way,\nThe preservation of the Three upon me to-night.\nOh! the Three -to shield me to-night.","note":"Said at nightfall, asking the Three, Michael, Mary, and Bride to keep a weary body on the right path.","voice":"brian","source":{"name":"Carmina Gadelica, vol. 1, Alexander Carmichael (1900)","url":"https://archive.org/details/carminagadelicah01carm_0/page/47/mode/1up"},"rights":"pd","pd":"published 1900; Carmichael died 1912"},{"id":"celtx-cg-sleep-consecration-mary","title":"I Lie Down To-night With Fair Mary","by":"Traditional (Scottish Gaelic)","tr":"Alexander Carmichael","year":1900,"trad":["celtic","christian"],"denom":["scottish"],"type":"prayer","occasion":["evening","forgiveness"],"text":"I lie down to-night\nWith fair Mary and with her Son,\nWith pure-white Michael,\nAnd with Bride beneath her corslet.\n\nI lie down with God,\nAnd God will lie down with me,\nI will not lie down with Satan,\nNor shall Satan lie down with me.\n\nO God of the poor,\nHelp me this night,\nOmit me not entirely\nFrom Thy treasure-house.\n\nFor the many wounds\nThat I inflicted on Thee,\nEnumerate them.\n\nThou King of the blood of truth,\nDo not forget me in Thy dwelling-place,\nDo not exact from me for my transgressions,\nDo not omit me in Thine ingathering.\nIn Thine ingathering.","note":"A bedtime prayer of lying down with God, Mary, Michael, and Bride, asking to be gathered in.","voice":"brian","source":{"name":"Carmina Gadelica, vol. 1, Alexander Carmichael (1900)","url":"https://archive.org/details/carminagadelicah01carm_0/page/81/mode/1up"},"rights":"pd","pd":"published 1900; Carmichael died 1912"},{"id":"celtx-cg-hail-to-thee-mary","title":"Hail to Thee, Mary, Mother","by":"Traditional (Scottish Gaelic)","tr":"Alexander Carmichael","year":1900,"trad":["celtic","christian","catholic"],"denom":["scottish"],"type":"prayer","occasion":["daily","dying"],"text":"Hail to thee, Mary, Mother!\nThou art full of loving grace,\nThe Lord God is always with thee,\nBlessed art thou Mary among women,\nBlessed is the fruit of thy womb, Jesus,\nBlessed art thou, Queen of grace;\nThou holy Mary, thou Mother of Jesus,\nPlead for me a miserable sinner,\nNow and at the hour of death,\nNow and at the hour of death!","note":"The Hebridean form of the Hail Mary, said at any hour and at the hour of death.","voice":"brian","source":{"name":"Carmina Gadelica, vol. 1, Alexander Carmichael (1900)","url":"https://archive.org/details/carminagadelicah01carm_0/page/111/mode/1up"},"rights":"pd","pd":"published 1900; Carmichael died 1912"},{"id":"celtx-cg-gift-of-power","title":"The Gift of Power","by":"Traditional (Scottish Gaelic)","tr":"Alexander Carmichael","year":1900,"trad":["celtic","christian"],"denom":["scottish"],"type":"chant","occasion":["season","blessing"],"text":"I am the Gift, I am the Poor,\nI am the Man of the night.\nI am the Son of God in the door,\nOn Monday seeking the gifts.\n\nNoble is Bride the gentle fair on her knee,\nNoble the King of glory on her breast.\nSon of the moon, Son of the sun,\nSon of great Mary of God-like mind.\n\nA cross on each right shoulder,\nI am in the door, open thou.\nI see the hills, I see the strands,\nI see angels heralding on high.\n\nI see the dove shapely, benign,\nComing with kindness and friendship to us.","note":"A Christmas visitor's chant at the door, seeing hills, strands, angels, and the dove of peace.","voice":"brian","source":{"name":"Carmina Gadelica, vol. 1, Alexander Carmichael (1900)","url":"https://archive.org/details/carminagadelicah01carm_0/page/143/mode/1up"},"rights":"pd","pd":"published 1900; Carmichael died 1912"},{"id":"celtx-cg-virgin-child-door","title":"The Virgin and Child at the Door","by":"Traditional (Scottish Gaelic)","tr":"Alexander Carmichael","year":1900,"trad":["celtic","christian"],"denom":["scottish"],"type":"chant","occasion":["season","home","blessing"],"text":"Behold the Virgin approaching\nChrist so young on her breast.\nO Mary Virgin! and O Holy Son!\n\nBless Ye the house and all therein.\nBless Ye the food, bless Ye the board,\nBless Ye the corn, the flock and the store.\n\nWhat time to us the quarter was scarce,\nIt is thou thyself, Virgin, who wast mother to us.\nThou art brighter than the waxing moon\nRising over the mountains.\n\nThou art brighter than the summer sun,\nUnder his fulness of joy.\nSince the bard must not tarry,\nPlace ye alms in the bag with a blessing.\n\nServant am I of God the Son at the door,\nFrom the bosom of God, arise thyself and open to me.","note":"Sung by the Christmas visitors at the door, blessing the house, the food, the board, and the store.","voice":"brian","source":{"name":"Carmina Gadelica, vol. 1, Alexander Carmichael (1900)","url":"https://archive.org/details/carminagadelicah01carm_0/page/145/mode/1up"},"rights":"pd","pd":"published 1900; Carmichael died 1912"},{"id":"celtx-cg-song-of-hogmanay","title":"The Song of Hogmanay","by":"Traditional (Scottish Gaelic)","tr":"Alexander Carmichael","year":1900,"trad":["celtic","christian"],"denom":["scottish"],"type":"song","occasion":["season","celebration","home"],"text":"Now since we came to the country\nTo renew to you the Hogmanay,\nTime will not allow us to explain,\nIt has been since the age of our fathers.\n\nAscending the wall of the house,\nDescending at the door,\nMy carol to say modestly,\nAs becomes me at the Hogmanay.\n\nThe Hogmanay skin is in my pocket,\nGreat the fume that will come from that,\nNo one who shall inhale its odour,\nBut shall be for ever from it healthy.\n\nThe house-man will get it in his grasp,\nHe will put its point in the fire,\nHe will go sunwise round the children,\nAnd very specially round the goodwife.\n\nThe wife will get it, she it is who deserves it,\nThe hand to distribute the Hogmanay,\nThe hand to bestow upon us cheese and butter,\nSince drought has come upon the land,\nAnd that we do not expect rarity,\nA little of the substance of the summer,\nWould we desire with the bread.\n\nIf that we are not to have it,\nIf thou mayest, do not detain us,\nI am the servant of God's Son on Hogmanay,\nArise thyself and open the door.","note":"Sung by the Hogmanay visitors on New Year's Eve as they bless the household and the goodwife.","voice":"brian","source":{"name":"Carmina Gadelica, vol. 1, Alexander Carmichael (1900)","url":"https://archive.org/details/carminagadelicah01carm_0/page/153/mode/1up"},"rights":"pd","pd":"published 1900; Carmichael died 1912"},{"id":"celtx-cg-genealogy-bride","title":"The Genealogy of Bride","by":"Traditional (Scottish Gaelic)","tr":"Alexander Carmichael","year":1900,"trad":["celtic","christian"],"denom":["scottish"],"type":"prayer","occasion":["daily","peace"],"text":"The genealogy of the holy maiden Bride,\nRadiant flame of gold, noble foster-mother of Christ.\nBride the daughter of Dugall the brown,\nSon of Aodh, son of Art, son of Conn,\nSon of Crearar, son of Cis, son of Carmac, son of Carruin.\n\nEvery day and every night\nThat I say the genealogy of Bride,\nI shall not be killed, I shall not be harried,\nI shall not be put in cell, I shall not be wounded,\nNeither shall Christ leave me in forgetfulness.\n\nNo fire, no sun, no moon shall burn me,\nNo lake, no water, nor sea shall drown me,\nNo arrow of fairy nor dart of fay shall wound me,\nAnd I under the protection of my Holy Mary,\nAnd my gentle foster-mother is my beloved Bride.","note":"Said on Saint Bride's Day and every day, naming the line of Bride, radiant flame of gold, for her keeping.","voice":"brian","source":{"name":"Carmina Gadelica, vol. 1, Alexander Carmichael (1900)","url":"https://archive.org/details/carminagadelicah01carm_0/page/175/mode/1up"},"rights":"pd","pd":"published 1900; Carmichael died 1912"},{"id":"celtx-cg-magnus","title":"Magnus of My Love","by":"Traditional (Scottish Gaelic)","tr":"Alexander Carmichael","year":1900,"trad":["celtic","christian"],"denom":["scottish"],"type":"prayer","occasion":["nature","blessing"],"text":"O Magnus of my love\nThou it is who would'st us guide,\nThou fragrant body of grace,\nRemember us.\n\nRemember us, thou Saint of power,\nWho didst encompass and protect the people,\nSuccour thou us in our distress,\nNor forsake us.\n\nLift our flocks to the hills,\nQuell the wolf and the fox,\nWard from us spectre, giant, fury,\nAnd oppression.\n\nSurround cows and herds,\nSurround sheep and lambs,\nKeep from them the water-vole,\nAnd the field-vole.\n\nSprinkle dew from the sky upon kine,\nGive growth to grass, and corn, and sap to plants,\nWater-cress, deer's-grass, 'ceis,' burdock,\nAnd daisy.\n\nO Magnus of fame,\nOn the barque of the heroes,\nOn the crest of the waves,\nOn the sea, on the land,\nAid and preserve us.","note":"A prayer to Saint Magnus for the flocks, the grass, the corn, and all who travel the sea and land.","voice":"brian","source":{"name":"Carmina Gadelica, vol. 1, Alexander Carmichael (1900)","url":"https://archive.org/details/carminagadelicah01carm_0/page/179/mode/1up"},"rights":"pd","pd":"published 1900; Carmichael died 1912"},{"id":"celtx-cg-beltane-mary","title":"The Beltane Blessing of Mary","by":"Traditional (Scottish Gaelic)","tr":"Alexander Carmichael","year":1900,"trad":["celtic","christian"],"denom":["scottish"],"type":"blessing","occasion":["season","nature"],"text":"Mary, thou mother of saints,\nBless our flocks and bearing kine,\nHate nor scath let not come near us,\nDrive from us the ways of the wicked.\n\nKeep thine eye every Monday and Tuesday\nOn the bearing kine and the pairing queys,\nAccompany us from hill to sea,\nGather thyself the sheep and their progeny.\n\nEvery Wednesday and Thursday be with them,\nBe thy gracious hand always about them,\nTend the cows down to their stalls,\nTend the sheep down to their folds!\n\nEvery Friday be thou, O Saint, at their head,\nLead the sheep from the face of the bens,\nWith their innocent little lambs following them,\nEncompass them with God's encompassing.\n\nEvery Saturday be likewise with them,\nBring the goats in with their young,\nEvery kid and goat to the sea side,\nAnd from the Rock of Aegir on high,\nWith cresses green about its summit.","note":"A May Day blessing asking Mary to tend the flocks every day of the week, from hill to sea.","voice":"brian","source":{"name":"Carmina Gadelica, vol. 1, Alexander Carmichael (1900)","url":"https://archive.org/details/carminagadelicah01carm_0/page/187/mode/1up"},"rights":"pd","pd":"published 1900; Carmichael died 1912"},{"id":"celtx-cg-procession","title":"Hymn of the Procession","by":"Traditional (Scottish Gaelic)","tr":"Alexander Carmichael","year":1900,"trad":["celtic","christian"],"denom":["scottish"],"type":"hymn","occasion":["season","blessing","nature"],"text":"Valiant Michael of the white steeds,\nWho subdued the Dragon of blood,\nFor love of God, for pains of Mary's Son,\nSpread thy wing over us, shield us all,\nSpread thy wing over us, shield us all.\n\nMary beloved! Mother of the White Lamb,\nShield, oh shield us, pure Virgin of nobleness,\nAnd Bride the beauteous, shepherdess of the flocks,\nSafeguard thou our cattle, surround us together,\nSafeguard thou our cattle, surround us together.\n\nAnd Columba, beneficent, benign,\nIn name of Father, and of Son, and of Spirit Holy,\nThrough the Three-in-One, through the Trinity,\nEncompass thou ourselves, shield our procession,\nEncompass thou ourselves, shield our procession.\n\nO Father! O Son! O Spirit Holy!\nBe the Triune with us day and night,\nOn the machair plain or on the mountain ridge\nBe the Triune with us and His arm around our head,\nBe the Triune with us and His arm around our head.","note":"Sung on Saint Michael's Day as the people walked sunwise round the burial ground, asking the Triune to be with them day and night.","voice":"brian","source":{"name":"Carmina Gadelica, vol. 1, Alexander Carmichael (1900)","url":"https://archive.org/details/carminagadelicah01carm_0/page/193/mode/1up"},"rights":"pd","pd":"published 1900; Carmichael died 1912"},{"id":"celtx-cg-struan","title":"The Blessing of the Struan","by":"Traditional (Scottish Gaelic)","tr":"Alexander Carmichael","year":1900,"trad":["celtic","christian"],"denom":["scottish"],"type":"blessing","occasion":["season","gratitude","home"],"text":"Each meal beneath my roof,\nThey will all be mixed together,\nIn name of God the Son,\nWho gave them growth.\n\nMilk, and eggs, and butter,\nThe good produce of our own flock,\nThere shall be no dearth in our land,\nNor in our dwelling.\n\nIn name of Michael of my love,\nWho bequeathed to us the power,\nWith the blessing of the Lamb,\nAnd of His Mother.\n\nHumble us at thy footstool,\nBe thine own sanctuary around us,\nWard from us spectre, sprite, oppression,\nAnd preserve us.\n\nConsecrate the produce of our land,\nBestow prosperity and peace,\nIn name of the Father the King,\nAnd of the three beloved apostles.\n\nDandelion, smooth garlic,\nGray 'cailpeach 'plucked,\nThe seven-pronged seven times,\nThe mountain yew, ruddy heath,\nAnd madder.\n\nI will put water on them all,\nIn precious name of the Son of God,\nIn name of Mary the generous,\nAnd of Patrick.\n\nWhen we shall sit down\nTo take our food,\nI will sprinkle in the name of God\nOn the children.","note":"Said over the Michaelmas cake of all the grains of the year, blessing the food and the children at the table.","voice":"brian","source":{"name":"Carmina Gadelica, vol. 1, Alexander Carmichael (1900)","url":"https://archive.org/details/carminagadelicah01carm_0/page/215/mode/1up"},"rights":"pd","pd":"published 1900; Carmichael died 1912"},{"id":"celtx-cg-hymn-sunday","title":"Hymn of the Sunday","by":"Traditional (Scottish Gaelic)","tr":"Alexander Carmichael","year":1900,"trad":["celtic","christian"],"denom":["scottish"],"type":"hymn","occasion":["daily","peace"],"text":"On the holy Sunday of thy God\nGive thou thine heart to all mankind,\nTo thy father and thy mother loving,\nBeyond any person or thing in the world.\n\nDo not covet large or small,\nDo not despise weakling or poor,\nSemblance of evil allow not near thee,\nNever give nor earn thou shame.\n\nThe ten commands God gave thee,\nUnderstand them early and prove,\nBelieve direct in the King of the elements,\nPut behind thee ikon-worship.\n\nBe faithful to thine over-lord,\nBe true to thy king in every need,\nBe true to thine own self besides,\nTrue to thy High-King above all obstacles.\n\nDo not thou malign any man,\nLest thou thyself maligned shouldst be,\nAnd shouldst thou travel earth and ocean,\nFollow the very step of God's Anointed.","note":"A Sunday teaching in verse: give your heart to all, honor your parents, be true to yourself and to God.","voice":"brian","source":{"name":"Carmina Gadelica, vol. 1, Alexander Carmichael (1900)","url":"https://archive.org/details/carminagadelicah01carm_0/page/225/mode/1up"},"rights":"pd","pd":"published 1900; Carmichael died 1912"},{"id":"celtx-cg-smooring-blessing","title":"Smooring Blessing","by":"Traditional (Scottish Gaelic)","tr":"Alexander Carmichael","year":1900,"trad":["celtic","christian"],"denom":["scottish"],"type":"blessing","occasion":["evening","home"],"text":"I will smoor the hearth\nAs Mary would smoor,\nThe encompassment of Bride and of Mary,\nOn the fire, and on the floor,\nAnd on the household all.\n\nWho is on the lawn without?\nFairest Mary and her Son,\nThe mouth of God ordained, the angel of God spoke;\nAngels of promise watching the hearth,\nTill white day comes to the fire.","note":"Said while covering the peat fire for the night, so angels keep the hearth till white day.","voice":"brian","source":{"name":"Carmina Gadelica, vol. 1, Alexander Carmichael (1900)","url":"https://archive.org/details/carminagadelicah01carm_0/page/243/mode/1up"},"rights":"pd","pd":"published 1900; Carmichael died 1912"},{"id":"celtx-cg-milking-brendan","title":"Milking Croon","by":"Traditional (Scottish Gaelic)","tr":"Alexander Carmichael","year":1900,"trad":["celtic","christian"],"denom":["scottish"],"type":"song","occasion":["daily","nature","home"],"text":"Come, Brendan, from the ocean,\nCome, Ternan, most potent of men,\nCome, Michael valiant, down\nAnd propitiate to me the cow of my joy.\n\nHo my heifer, ho heifer of my love,\nHo my heifer, ho heifer of my love.\nMy beloved heifer, choice cow of every sheiling,\nFor the sake of the High King take to thy calf.\n\nCome, beloved Colum of the fold,\nCome, great Bride of the flocks,\nCome, fair Mary from the cloud,\nAnd propitiate to me the cow of my love.\n\nHo my heifer, ho heifer of my love.\nThe stock-dove will come from the wood,\nThe tusk will come from the wave,\nThe fox will come but not with wiles,\nTo hail my cow of virtues.\nHo my heifer, ho heifer of my love.","note":"A milking song sung softly to the cow, calling on the saints to come and bless the milking.","voice":"brian","source":{"name":"Carmina Gadelica, vol. 1, Alexander Carmichael (1900)","url":"https://archive.org/details/carminagadelicah01carm_0/page/259/mode/1up"},"rights":"pd","pd":"published 1900; Carmichael died 1912"},{"id":"celtx-cg-milking-columba","title":"Milking Blessing","by":"Traditional (Scottish Gaelic)","tr":"Alexander Carmichael","year":1900,"trad":["celtic","christian"],"denom":["scottish"],"type":"song","occasion":["daily","nature"],"text":"Columba will give to her progeny,\nCoivi the propitious, will give to her grass,\nMy speckled heifer will give me her milk,\nAnd her female calf before her.\n\nHo my heifer! kindly, calm,\nMy heifer gentle, gentle, beloved,\nThou art the love of thy mother.\n\nSeest yonder thriving bramble bush\nAnd the other bush glossy with brambles,\nSuch like is my fox-coloured heifer,\nAnd her female calf before her.\n\nHo my heifer!\nThe calm Bride of the white combs\nWill give to my loved heifer the lustre of the swan,\nWhile the loving Mary, of the combs of honey,\nWill give to her the mottle of the heather hen.","note":"A gentle milking song for a speckled heifer, with gifts from Columba, Bride, and Mary.","voice":"brian","source":{"name":"Carmina Gadelica, vol. 1, Alexander Carmichael (1900)","url":"https://archive.org/details/carminagadelicah01carm_0/page/263/mode/1up"},"rights":"pd","pd":"published 1900; Carmichael died 1912"},{"id":"celtx-cg-milking-song","title":"Milking Song","by":"Traditional (Scottish Gaelic)","tr":"Alexander Carmichael","year":1900,"trad":["celtic","christian"],"denom":["scottish"],"type":"song","occasion":["daily","nature","home"],"text":"Come, Mary, and milk my cow\nCome, Bride, and encompass her,\nCome, Columba the benign,\nAnd twine thine arms around my cow,\nHo my heifer, ho my gentle heifer,\nHo my heifer, ho my gentle heifer,\nHo my heifer, ho my gentle heifer,\nMy heifer full of heart, generous and kind,\nFor the sake of the High King take to thy calf.\n\nCome, Mary Virgin, to my cow,\nCome, great Bride, the beauteous,\nCome, thou milkmaid of Jesus Christ,\nAnd place thine arms beneath my cow.\n\nHo my heifer, ho my gentle heifer.\nThe night the Herdsman was out,\nNo shackle went on a cow,\nNor ceased lowing from the mouth of calf,\nWailing the Herdsman of the cattle.\n\nHo my heifer, ho my gentle heifer.\nLovely black cow, pride of the sheiling,\nFirst cow of the byre, choice mother of calves,\nWisps of straw round the cows of the townland.\nA shackle of silk on my heifer beloved.","note":"Sung at the milking, asking Mary, Bride, and Columba to come and twine their arms around the cow.","voice":"brian","source":{"name":"Carmina Gadelica, vol. 1, Alexander Carmichael (1900)","url":"https://archive.org/details/carminagadelicah01carm_0/page/273/mode/1up"},"rights":"pd","pd":"published 1900; Carmichael died 1912"},{"id":"celtx-cg-herding-keeping","title":"Herding Blessing: The Keeping of God","by":"Traditional (Scottish Gaelic)","tr":"Alexander Carmichael","year":1900,"trad":["celtic","christian"],"denom":["scottish"],"type":"blessing","occasion":["blessing","nature","peace"],"text":"The keeping of God and the Lord on you,\nThe keeping of Christ always on you,\nThe keeping of Carmac and of Columba on you,\nThe keeping of Cairbre on you going and coming,\nAnd the keeping of Ariel the gold-bright on you,\nThe keeping of Ariel the gold-bright on you.\n\nThe keeping of Bride the foster-mother on you,\nThe keeping of Mary the yellow-haired on you,\nOf Christ Jesus, the Son of peace,\nThe King of kings, land and sea,\nAnd the peace-giving Spirit, everlasting, be yours,\nThe peace-giving Spirit, everlasting, be yours.","note":"Said as the cattle go out to pasture, a gentle sending that also serves any loved one setting out.","voice":"brian","source":{"name":"Carmina Gadelica, vol. 1, Alexander Carmichael (1900)","url":"https://archive.org/details/carminagadelicah01carm_0/page/277/mode/1up"},"rights":"pd","pd":"published 1900; Carmichael died 1912"},{"id":"celtx-cg-herding-flock-before","title":"Herding Blessing: I Will Place This Flock","by":"Traditional (Scottish Gaelic)","tr":"Alexander Carmichael","year":1900,"trad":["celtic","christian"],"denom":["scottish"],"type":"blessing","occasion":["blessing","nature"],"text":"I will place this flock before me\nAs was ordained of the King of the world,\nBride to keep them, to watch them, to tend them,\nOn ben, on glen, on plain,\nBride to keep them, to watch them, to tend them,\nOn ben, on glen, on plain.\n\nArise, thou Bride the gentle, the fair,\nTake thou thy lint, thy comb, and thy hair,\nSince thou to them madest the rich charm,\nTo keep them from straying, to save them from harm.\n\nSince thou to them madest the rich charm,\nTo keep them from straying, to save them from harm.\nFrom rocks, from drifts, from streams,\nFrom crooked passes, from destructive pits,\nFrom the straight arrows of the slender ban-shee,\nFrom the heart of envy, from the eye of evil,\nFrom the straight arrows of the slender ban-shee,\nFrom the heart of envy, from the eye of evil.\n\nMary Mother, tend thou the offspring all,\nBride of the fair palms, guard thou my flocks,\nKindly Columba, thou saint of many powers,\nEncompass thou the breeding cows, bestow on me herds,\nKindly Columba, thou saint of many powers,\nEncompass thou the breeding cows, bestow on me herds.","note":"Said by the herder in the morning, asking Bride, Mary, and Columba to keep the flock on ben, glen, and plain.","voice":"brian","source":{"name":"Carmina Gadelica, vol. 1, Alexander Carmichael (1900)","url":"https://archive.org/details/carminagadelicah01carm_0/page/279/mode/1up"},"rights":"pd","pd":"published 1900; Carmichael died 1912"},{"id":"celtx-cg-clipping","title":"The Clipping Blessing","by":"Traditional (Scottish Gaelic)","tr":"Alexander Carmichael","year":1900,"trad":["celtic","christian"],"denom":["scottish"],"type":"blessing","occasion":["nature","blessing"],"text":"Go shorn and come woolly,\nBear the Beltane female lamb,\nBe the lovely Bride thee endowing,\nAnd the fair Mary thee sustaining,\nThe fair Mary sustaining thee.\n\nMichael the chief be shielding thee\nFrom the evil dog and from the fox,\nFrom the wolf and from the sly bear.\n\nAnd from the taloned birds of destructive bills,\nFrom the taloned birds of hooked bills.","note":"Said as each newly shorn sheep is set free, blessing it on its way.","voice":"brian","source":{"name":"Carmina Gadelica, vol. 1, Alexander Carmichael (1900)","url":"https://archive.org/details/carminagadelicah01carm_0/page/297/mode/1up"},"rights":"pd","pd":"published 1900; Carmichael died 1912"},{"id":"celtx-cg-loom-thrums","title":"Loom Blessing","by":"Traditional (Scottish Gaelic)","tr":"Alexander Carmichael","year":1900,"trad":["celtic","christian"],"denom":["scottish"],"type":"blessing","occasion":["daily","gratitude"],"text":"Thrums nor odds of thread\nMy hand never kept, nor shall keep,\nEvery colour in the bow of the shower\nHas gone through my fingers beneath the cross,\nWhite and black, red and madder,\nGreen, dark grey, and scarlet,\nBlue, and roan, and colour of the sheep,\nAnd never a particle of cloth was wanting.\n\nI beseech calm Bride the generous,\nI beseech mild Mary the loving,\nI beseech Christ Jesu the humane,\nThat I may not die without them.\nThat I may not die without them.","note":"A weaver's blessing of honest work, with every colour of the rainbow passing through her fingers.","voice":"brian","source":{"name":"Carmina Gadelica, vol. 1, Alexander Carmichael (1900)","url":"https://archive.org/details/carminagadelicah01carm_0/page/305/mode/1up"},"rights":"pd","pd":"published 1900; Carmichael died 1912"},{"id":"celtx-cg-iomairt","title":"Setting the Iomairt","by":"Traditional (Scottish Gaelic)","tr":"Alexander Carmichael","year":1900,"trad":["celtic","christian"],"denom":["scottish"],"type":"chant","occasion":["daily","home"],"text":"The black by the white,\nThe white by the black,\nThe green in the middle of the red,\nThe red in the middle of the black.\n\nThe black in the middle of the red,\nThe red in the middle of the white,\nThe white in the middle of the green,\nThe green in the middle of the white.\n\nThe white in the middle of the blue,\nThe blue in the middle of the scarlet,\nThe scarlet to the blue,\nThe blue to the scarlet,\nThe scarlet to the black,\nThe black to the scarlet.\n\nA thread to two threads\nOf two colours.\nTwo threads of black\nTo one thread of white.\n\nSeven threads to five,\nFive to three,\nThree to two,\n'Two to one,\nIn each border.","note":"A weaver's chant for setting the pattern of the tartan, thread by thread and colour by colour.","voice":"brian","source":{"name":"Carmina Gadelica, vol. 1, Alexander Carmichael (1900)","url":"https://archive.org/details/carminagadelicah01carm_0/page/307/mode/1up"},"rights":"pd","pd":"published 1900; Carmichael died 1912"},{"id":"celtx-cg-ocean-father","title":"Ocean Blessing","by":"Traditional (Scottish Gaelic)","tr":"Alexander Carmichael","year":1900,"trad":["celtic","christian"],"denom":["scottish"],"type":"blessing","occasion":["blessing","peace"],"text":"God the Father all-powerful, benign,\nJesu the Son of tears and of sorrow,\nWith thy co-assistance, O! Holy Spirit.\n\nThe Three-One, ever-living, ever-mighty, everlasting,\nWho brought the Children of Israel through the Red Sea,\nWho brought Paul and his companions in the ship,\nFrom the torment of the sea, from the dolour of the waves,\nWhen the storm poured on the Sea of Galilee,\nSain us and shield and sanctify us,\nBe Thou, King of the elements, seated at our helm,\nAnd lead us in peace to the end of our journey.\n\nWith winds mild, kindly, benign, pleasant,\nWithout swirl, without whirl, without eddy,\nThat would do no harmful deed to us.\n\nWe ask all things of Thee, O God,\nAccording to Thine own will and word.","note":"Said by the crew before putting out to sea, asking the King of the elements to sit at the helm.","voice":"brian","source":{"name":"Carmina Gadelica, vol. 1, Alexander Carmichael (1900)","url":"https://archive.org/details/carminagadelicah01carm_0/page/333/mode/1up"},"rights":"pd","pd":"published 1900; Carmichael died 1912"},{"id":"celtx-cg-sleep-prayer-jesu","title":"Sleep Prayer","by":"Traditional (Scottish Gaelic)","tr":"Alexander Carmichael","year":1900,"trad":["celtic","christian"],"denom":["scottish"],"type":"prayer","occasion":["evening","dying"],"text":"O Jesu without sin,\nKing of the poor,\nWho wert sorely subdued\nUnder ban of the wicked,\nShield Thou me this night\nFrom Judas.\n\nMy soul on Thine own arm, O Christ,\nThou the King of the City of Heaven,\nThou it was who bought'st my soul, O Jesu,\nThou it was who didst sacrifice Thy life for me.\n\nProtect Thou me because of my sorrow,\nFor the sake of Thy passion, Thy wounds, and Thy blood,\nAnd take me in safety to-night\nNear to the City of God.","note":"A night prayer placing the soul on the arm of Christ and asking for a safe journey near to the City of God.","voice":"brian","source":{"name":"Carmina Gadelica, vol. 1, Alexander Carmichael (1900)","url":"https://archive.org/details/carminagadelicah01carm_0/page/77/mode/1up"},"rights":"pd","pd":"published 1900; Carmichael died 1912"},{"id":"celtx-cg-kertch","title":"The Kertch: A Bride's Blessing","by":"Traditional (Scottish Gaelic)","tr":"Alexander Carmichael","year":1900,"trad":["celtic","christian"],"denom":["scottish"],"type":"blessing","occasion":["wedding","blessing","home"],"text":"A thousand hails to thee beneath thy kertch,\nDuring thy course mayest thou be whole,\nStrength and days be thine in peace,\nThy paradise with thy means increase.\n\nIn beginning thy dual race, and thou young,\nIn beginning thy course, seek thou the God of life,\nFear not but He will rightly rule\nThine every secret need and prayer.\n\nThis spousal crown thou now hast donned,\nFull oft has gotten grace to woman,\nBe thou virtuous, but be gracious,\nBe thou pure in word and hand.\n\nBe thou hospitable, yet be wise,\nBe thou courageous, but be calm,\nBe thou frank, but be reserved,\nBe thou exact, yet generous.\n\nBe not miserly in giving,\nDo not flatter, yet be not cold,\nSpeak not ill of man, though ill he be,\nIf spoken of, show not resentment.\n\nBe thou careful of thy name,\nBe thou dignified yet kind,\nThe hand of God be on thine helm,\nIn inception, in act, and in thought.","note":"Sung to a young wife on the first Sunday she wore the kertch, the head-dress of a married woman: a wedding blessing full of good counsel.","voice":"brian","source":{"name":"Carmina Gadelica, vol. 2, Alexander Carmichael (1900)","url":"https://archive.org/details/carminagadelicah02carm_0/page/213/mode/1up"},"rights":"pd","pd":"published 1900; Carmichael died 1912"},{"id":"celtx-cg-first-miracle","title":"The First Miracle of Christ","by":"Traditional (Scottish Gaelic)","tr":"Alexander Carmichael","year":1900,"trad":["celtic","christian"],"denom":["scottish"],"type":"story","occasion":["season","birth","celebration"],"text":"Joseph and Mary went\nTo the numbering up,\nAnd the birds began chorusing\nIn the woods of the turtle-doves.\n\nThe two were walking the way,\nTill they reached a thick wood,\nAnd in the wood there was fruit\nWhich was as red as the rasp.\n\nThat was the time when she was great,\nThat she was carrying the King of grace,\nAnd she took a desire for the fruit\nThat was growing on the gracious slope.\n\nThen spoke Mary to Joseph\nIn a voice low and sweet,\n'Give to me of the fruit, Joseph,\nThat I may quench my desire.'\n\nAnd Joseph spoke to Mary,\nAnd the hard pain in his breast,\n'I will give thee of the fruit, Mary,\nBut who is the father of thy burthen?'\n\nThen it was that the Babe spoke,\nFrom out of her womb,\n'Bend ye down every beautiful bough,\nThat my Mother may quench her desire.'\n\nAnd from the bough that was highest,\nTo the bough that was lowest,\nThey all bent down to her knee,\nAnd Mary partook of the fruit\nIn her loved land of prophecy.\n\nThen Joseph said to Mary,\nAnd he full of heavy contrition,\n'It is carrying Him thou art,\nThe King of glory and of grace.\n\nBlessed art thou, Mary,\nAmong the women of all lands.\nBlessed art thou, Mary,\nAmong the women of all lands.'","note":"A Hebridean carol story of Joseph and Mary in the wood, where the trees bow down to the mother of the King of grace.","voice":"brian","source":{"name":"Carmina Gadelica, vol. 2, Alexander Carmichael (1900)","url":"https://archive.org/details/carminagadelicah02carm_0/page/163/mode/1up"},"rights":"pd","pd":"published 1900; Carmichael died 1912"},{"id":"celtx-cg-crucified","title":"From He Who Was Crucified","by":"Traditional (Scottish Gaelic)","tr":"Alexander Carmichael","year":1900,"trad":["celtic","christian"],"denom":["scottish"],"type":"prayer","occasion":["forgiveness","hope","season"],"text":"Thou who wert hanged upon the tree\nAnd wert crucified by the condemnation of the people,\nNow that I am grown old and grey,\nTake to my confession-prayer, O God! pity.\n\nNo wonder to me great is my wickedness,\nI am a poor clattering cymbal,\nIn my youth I was profane,\nIn my age I am forlorn.\n\nA time ere came the Son of God,\nThe earth was a black morass,\nWithout star, without sun, without moon,\nWithout body, without heart, without form.\n\nIllumined plains, illumined hills,\nIllumined the great green sea,\nIllumined the whole globe together,\nWhen the Son of God came to earth.","note":"An old person's prayer of confession that turns to wonder at the light that came with the Son of God.","voice":"brian","source":{"name":"Carmina Gadelica, vol. 2, Alexander Carmichael (1900)","url":"https://archive.org/details/carminagadelicah02carm_0/page/173/mode/1up"},"rights":"pd","pd":"published 1900; Carmichael died 1912"},{"id":"celtx-cg-fragment","title":"As It Was, As It Is","by":"Traditional (Scottish Gaelic)","tr":"Alexander Carmichael","year":1900,"trad":["celtic","christian"],"denom":["scottish"],"type":"blessing","occasion":["daily","peace","dying","funeral"],"text":"As it was,\nAs it is,\nAs it shall be\nEvermore,\nO Thou Triune\nOf grace!\n\nWith the ebb,\nWith the flow,\nO Thou Triune\nOf grace!\n\nWith the ebb,\nWith the flow.","note":"A small doxology from the islands, fitting for the close of any prayer or a quiet moment at the end of a life.","voice":"brian","source":{"name":"Carmina Gadelica, vol. 2, Alexander Carmichael (1900)","url":"https://archive.org/details/carminagadelicah02carm_0/page/217/mode/1up"},"rights":"pd","pd":"published 1900; Carmichael died 1912"},{"id":"celtx-cg-christ-the-priest","title":"Christ the Priest Above Us","by":"Traditional (Scottish Gaelic)","tr":"Alexander Carmichael","year":1900,"trad":["celtic","christian"],"denom":["scottish"],"type":"litany","occasion":["season","celebration"],"text":"Christ the Priest above us,\nOrdained of God for all living.\nChrist the Priest above us.\n\nTo-night, the night of the cross of agony,\nThe cross of anguish to which Christ was crucified.\nChrist the Priest above us.\n\nNoble the Gift! noble the Poor!\nNoble the Man of this night.\nChrist the Priest above us.\n\nIt was Bride the fair who went on her knee,\nIt is the King of glory who is in her lap.\nChrist the Priest above us.\n\nI hear the hills, I hear the seas,\nI hear the angels heralding to earth\nChrist the Priest above us.\n\nI hear Cairbre of the shapely, rounded limbs,\nComing softly in friendship to us.\nChrist the Priest above us.\n\nGreat the assemblage upon this knoll,\nWithout the envy of man to another.\nChrist the Priest above us.\n\nI am servant of God the Son at the door,\nOh! arise thou thyself and open to me.\nChrist the Priest above us.","note":"A Hebridean Christmas Eve chant answered again and again with Christ the Priest above us.","voice":"brian","source":{"name":"Carmina Gadelica, vol. 1, Alexander Carmichael (1900)","url":"https://archive.org/details/carminagadelicah01carm_0/page/161/mode/1up"},"rights":"pd","pd":"published 1900; Carmichael died 1912"},{"id":"celtx-cg-prayer-for-protection","title":"Prayer for Protection","by":"Traditional (Scottish Gaelic)","tr":"Alexander Carmichael","year":1900,"trad":["celtic","christian"],"denom":["scottish"],"type":"prayer","occasion":["daily","peace"],"text":"As Thou art the Shepherd over the flock\nTend Thou us to the cot and the fold,\nSain us beneath Thine own glorious mantle,\nThou Shield of protection, guard us for ever.\n\nBe Thou a hard triumphant glave\nTo shield us securely from wicked hell,\nFrom the fiends and from the stieve snell gullies.\nAnd from the lurid smoke of the abyss.\n\nMy soul is in the trustance of the High King,\nMichael the powerful is in charge of my soul.","note":"A short prayer to the Shepherd of the flock, placing the soul in the keeping of the High King.","voice":"brian","source":{"name":"Carmina Gadelica, vol. 1, Alexander Carmichael (1900)","url":"https://archive.org/details/carminagadelicah01carm_0/page/37/mode/1up"},"rights":"pd","pd":"published 1900; Carmichael died 1912"},{"id":"celtx-cg-christmas-chant","title":"Christmas Chant","by":"Traditional (Scottish Gaelic)","tr":"Alexander Carmichael","year":1900,"trad":["celtic","christian"],"denom":["scottish"],"type":"chant","occasion":["season","celebration","home"],"text":"Ho, hail! blessed the King!\nHo, hi! let there be joy!\nProsperity be upon this dwelling,\nOn all that ye have heard and seen,\nOn the bare bright floor stones,\nOn the shapely standing stone staves,\nHail King! hail King! blessed is He! blessed is He!\n\nBless this house and all that it contains,\nFrom rafter and stone and beam,\nDeliver it to God from pall to cover,\nBe the healing of men therein,\nHail King! hail King! blessed is He! blessed is He!\n\nBe ye in lasting possession of the house,\nBe ye healthy about the hearth,\nMany be the ties and stakes in the homestead,\nPeople dwelling on this foundation,\nHail King! hail King! blessed is He! blessed is He!\n\nOffer to the Being from found to cover,\nInclude stave and stone and beam,\nOffer again both rods and cloth,\nBe health to the people therein,\nHail King! hail King! blessed is He! blessed is He!\n\nHail King! hail King! blessed is He! blessed is He!\nHo, hail! blessed the King!\nLet there be joy!\n\nBlessed the King,\nWithout beginning, without ending,\nTo everlasting, to eternity,\nEvery generation for aye,\nHo, hi! let there be joy!","note":"Chanted by the Christmas guisers at each house, blessing the dwelling, the hearth, and all within.","voice":"brian","source":{"name":"Carmina Gadelica, vol. 1, Alexander Carmichael (1900)","url":"https://archive.org/details/carminagadelicah01carm_0/page/135/mode/1up"},"rights":"pd","pd":"published 1900; Carmichael died 1912"},{"id":"celtx-cg-lords-day","title":"From the Poem of the Lord's Day","by":"Traditional (Scottish Gaelic)","tr":"Alexander Carmichael","year":1900,"trad":["celtic","christian"],"denom":["scottish"],"type":"poem","occasion":["daily","peace","nature"],"text":"The poem of the Lord's Day, O bright God,\nTruth under the strength of Christ always.\nOn the Lord's Day Mary was born,\nMother of Christ of golden yellow hair,\nOn the Lord's Day Christ was born\nAs an honour to men.\n\nThe Lord's Day, the seventh day,\nGod ordained to take rest,\nTo keep the life everlasting,\nWithout taking use of ox or man,\nOr of creature as Mary desired,\nWithout spinning thread of silk or of satin,\nWithout sewing, without embroidery either,\nWithout sowing, without harrowing, without reaping,\nWithout rowing, without games, without fishing,\nWithout going out to the hunting hill,\nWithout trimming arrows on the Lord's Day,\nWithout cleaning byre, without threshing corn,\nWithout kiln, without mill on the Lord's Day.\n\nWhosoever would keep the Lord's Day,\nEven would it be to him and lasting,\nFrom setting of sun on Saturday\nTill rising of sun on Monday.\n\nHe would obtain recompense therefrom,\nProduce after the ploughs,\nFish on the pure salt-water stream,\nFish excelling in every river confluence.\n\nThe water of the Lord's Day mild as honey,\nWhoso would partake of it as drink\nWould obtain health in consequence\nFrom every disease afflicting him.","note":"A Sabbath poem from the isles: Mary born and Christ born on the Lord's Day, the day ordained for rest.","voice":"brian","source":{"name":"Carmina Gadelica, vol. 1, Alexander Carmichael (1900)","url":"https://archive.org/details/carminagadelicah01carm_0/page/219/mode/1up"},"rights":"pd","pd":"published 1900; Carmichael died 1912"},{"id":"celtx-cg-bathing-prayer","title":"The Bathing Prayer","by":"Traditional (Scottish Gaelic)","tr":"Alexander Carmichael","year":1900,"trad":["celtic","christian"],"denom":["scottish"],"type":"blessing","occasion":["birth","blessing","home"],"text":"A palmful for thine age,\nA palmful for thy growth,\nA palmful for thy throat,\nA flood for thine appetite.\n\nFor thy share of the dainty,\nCrowdie and kail;\nFor thy share of the taking,\nHoney and warm milk.\n\nFor thy share of the supping,\nWhisked whey and milk-product;\nFor thy share of the spoil,\nWith bow and with spear.\n\nFor thy share of the preparation,\nThe yellow eggs of Easter:\nFor thy share of the treat,\nMy treasure and my joy,\n\nFor thy share of the feast\nWith gifts and with tribute;\nFor thy share of the treasure,\nPulset of my love.\n\nFor thy share of the chase\nUp the face of the Beinn-a-cheo;\nFor thy share of the hunting\nAnd the mustering of hosts.\n\nFor thy share of palaces,\nIn the courts of kings;\nFor thy share of Paradise\nWith its goodness and its peace.\n\nThe part of thee that does not grow at dawn,\nMay it grow at eventide;\nThe part of thee that does not grow at night,\nMay it grow at ridge of middle-day.\n\nThe three palmfuls\nOf the Secret Three,\nTo preserve thee\nFrom every envy,\n\nEvil eye and death;\nThe palmful of the God of Life,\nThe palmful of the Christ of Love,\nThe palmful of the Spirit of Peace.\n\nTriune\nOf Grace.","note":"Said by a mother as she pours three palmfuls of water over her newborn child, wishing it every good share in life.","voice":"brian","source":{"name":"Carmina Gadelica, vol. 1, Alexander Carmichael (1900)","url":"https://archive.org/details/carminagadelicah01carm_0/page/61/mode/1up"},"rights":"pd","pd":"published 1900; Carmichael died 1912"},{"id":"celtx-borrow-last-journey","title":"The Last Journey","by":"Huw Morus","tr":"George Borrow","year":1915,"trad":["celtic","christian"],"denom":["welsh"],"type":"poem","occasion":["dying","funeral","hope"],"text":"Now to my rest I hurry away,\nTo the world which lasts for ever and aye,\nTo Paradise, the beautiful place,\nTrusting alone in the Lord of Grace.","note":"A four line Welsh verse for the last journey, trusting in the Lord of grace.","voice":"brian","source":{"name":"Welsh Poems and Ballads, translated by George Borrow (1915)","url":"https://archive.org/details/welshpoemsballad00borruoft/page/142/mode/1up"},"rights":"pd","pd":"published 1915; Borrow died 1881"},{"id":"celtx-borrow-gods-better","title":"God's Better Than All","by":"Rhys Prichard, Vicar of Llandovery","tr":"George Borrow","year":1915,"trad":["celtic","christian"],"denom":["welsh"],"type":"poem","occasion":["daily","comfort","dying"],"text":"God's better than heaven or aught therein,\nThan the earth or aught we there can win,\nBetter than the world or its wealth to me,\nGod's better than all that is or can be.\n\nBetter than father, than mother, than nurse,\nBetter than riches, oft proving a curse,\nBetter than Martha or Mary even,\nBetter by far is the God of heaven.\n\nIf God for thy portion thou hast ta'en\nThere's Christ to support thee in every pain,\nThe world to respect thee thou wilt gain,\nTo fear the fiend and all his train.\n\nOf the best of portions thou choice didst make\nWhen thou the high God to thyself didst take,\nA portion which none from thy grasp can rend\nWhilst the sun and the moon on their course shall wend.\n\nWhen the sun grows dark and the moon turns red,\nWhen the stars shall drop and millions dread,\nWhen the earth shall vanish with its pomps in fire,\nThy portion still shall remain entire.\n\nThen let not thy heart though distressed, complain!\nA hold on thy portion firm maintain.\nThou didst choose the best portion, again I say,\nResign it not till thy dying day.","note":"A Welsh verse sermon from the Vicar of Llandovery: God is the portion no one can take away.","voice":"brian","source":{"name":"Welsh Poems and Ballads, translated by George Borrow (1915)","url":"https://archive.org/details/welshpoemsballad00borruoft/page/151/mode/1up"},"rights":"pd","pd":"published 1915; Borrow died 1881"},{"id":"celtx-borrow-earth-in-earth","title":"Earth in Earth: An Epitaph","by":"Traditional (Welsh)","tr":"George Borrow","year":1915,"trad":["celtic","christian"],"denom":["welsh"],"type":"poem","occasion":["funeral","grief"],"text":"Thou earth from earth reflect with anxious mind\nThat earth to earth must quickly be consigned,\nAnd earth in earth must lie entranced, enthralled,\nTill earth from earth to judgment shall be called.","note":"An old Welsh epitaph on earth returning to earth, fitting for a graveside.","voice":"brian","source":{"name":"Welsh Poems and Ballads, translated by George Borrow (1915)","url":"https://archive.org/details/welshpoemsballad00borruoft/page/150/mode/1up"},"rights":"pd","pd":"published 1915; Borrow died 1881"},{"id":"celtx-borrow-yew-tree","title":"To the Yew Tree on the Grave of Dafydd ab Gwilym","by":"After Gruffydd Gryg","tr":"George Borrow","year":1915,"trad":["celtic","all"],"denom":["welsh"],"type":"poem","occasion":["funeral","grief","nature"],"text":"Thou noble tree; who shelterest kind\nThe dead man's house from winter's wind:\nMay lightnings never lay thee low,\nNor archer cut from thee his bow;\nNor Crispin peel thee pegs to frame,\nBut may thou ever bloom the same,\nA noble tree the grave to guard\nOf Cambria's most illustrious bard!\n\nO tree of yew, which here I spy,\nBy Ystrad Flur's blest monast'ry,\nBeneath thee lies, by cold Death bound,\nThe tongue for sweetness once renown'd.\n\nBetter for thee thy boughs to wave,\nThough scath'd, above Ab Gwilym's grave,\nThan stand in pristine glory drest\nWhere some ignobler bard doth rest;\nI'd rather hear a taunting rhyme\nFrom one who'll live through endless time,\nThan hear my praises chanted loud\nBy poets of the vulgar crowd.","note":"A Welsh poem to the yew that shelters a beloved poet's grave at Strata Florida.","voice":"brian","source":{"name":"Welsh Poems and Ballads, translated by George Borrow (1915)","url":"https://archive.org/details/welshpoemsballad00borruoft/page/149/mode/1up"},"rights":"pd","pd":"published 1915; Borrow died 1881"},{"id":"celtx-borrow-mountain-snow","title":"The Mountain Snow","by":"Traditional (Welsh)","tr":"George Borrow","year":1915,"trad":["celtic","nature"],"denom":["welsh"],"type":"poem","occasion":["nature","season"],"text":"The mountain snow: the stag doth fly,\nThe wind about the roofs doth sigh.\nLove cannot in concealment lie.\n\nThe mountain snow: the grove is dark,\nThe raven black; the hound doth bark.\nGod keep you from all evil work.\n\nThe mountain snow: the crust is sound;\nThe wind doth twist the reeds around.\nWhere ignorance is, no grace is found.","note":"Old Welsh triplets that each begin with the mountain snow and end with a line of wisdom.","voice":"brian","source":{"name":"Welsh Poems and Ballads, translated by George Borrow (1915)","url":"https://archive.org/details/welshpoemsballad00borruoft/page/175/mode/1up"},"rights":"pd","pd":"published 1915; Borrow died 1881"},{"id":"celtx-borrow-icolmcill","title":"To Icolmcill","by":"Duncan Ban MacIntyre","tr":"George Borrow","year":1915,"trad":["celtic","christian"],"denom":["scottish"],"type":"poem","occasion":["blessing","funeral","nature"],"text":"On Icolmcill may blessings pour!\nIt is the island blest of yore;\nMull's sister-twin in the wild main,\nOwning the sway of high Mac-Lean;\nThe sacred spot, whose fair renown\nTo many a distant land has flown,\nAnd which receives in courteous way\nAll, all who thither chance to stray.\n\nThere in the grave are many a King\nAnd duine-wasself slumbering;\nAnd bodies, once of giant strength,\nBeneath the earth are stretch'd at length;\nIt is the fate of mortals all\nTo ashes fine and dust to fall;\nI've hope in Christ, for sins who died,\nHe has their souls beatified.\n\nNow full twelve hundred years, and more,\nOn dusky wing have flitted o'er,\nSince that high morn when Columb grey\nIts wall's foundation-stone did lay;\nImages still therein remain\nAnd death-memorials carv'd with pain;\nOf good hewn stone from top to base,\nIt shows to Time a dauntless face.\n\nA man this day the pulpit fill'd,\nWhose sermon brain and bosom thrill'd,\nAnd all the listening crowd I heard\nPraising the mouth which it proffer'd.\n\nSince death has seiz'd on Columb Cill,\nAnd Mull may not possess him still,\nThere's joy throughout its heathery lands,\nIn Columb's place that Dougal stands.","note":"A blessing on Iona, the island of Columba, where kings and common folk rest in hope.","voice":"brian","source":{"name":"Welsh Poems and Ballads, translated by George Borrow (1915)","url":"https://archive.org/details/welshpoemsballad00borruoft/page/191/mode/1up"},"rights":"pd","pd":"published 1915; Borrow died 1881"},{"id":"celtx-breton-flowers-of-may","title":"The Flowers of May","by":"Two Breton peasant sisters, names not given in the source","tr":"Tom Taylor","year":1865,"trad":["celtic","christian"],"denom":["breton"],"type":"song","occasion":["dying","grief","funeral"],"text":"On the sea-shore who Jeffik had seen\nWith rosy cheeks and eyes of sheen;\n\nWho for the pardon had seen her start,\nHad felt the happier in his heart:\n\nBut he that had seen her on her bed,\nHad tears of pity for her shed,\n\nTo see the sweet sick maiden laid,\nPale as a lily in summer-shade.\n\nTo her companions she said,\nThat sat beside her on her bed:\n\n\"My friends, if loving friends ye be,\nIn God's name, do not weep for me.\n\n\"You know all living death must dree;\nGod's own self died, died on the tree.\"\n\nAs I went for water to the spring\nI heard the nightingale sweetly sing:\n\n\"The month of May is passing e'en now,\nAnd with it the blossom on the bough.\n\n\"The happiest lot from life they bring,\nThe young whom death takes in the spring.\n\n\"Ev'n as the rose drops from the spray,\nSo youth from life doth fall away.\n\n\"Those who die ere this week is flown,\nAll with fresh flowers shall be strown;\n\n\"And from those flowers shall soar heaven-high,\nAs from the rose-cup the butterfly.\"\n\n\"Jeffik! Jeffik! did you not hear\nThe nightingale's song so sweet and clear?\n\n\"The month of May is passing e'en now,\nAnd with it the blossom on the bough.' \"\n\nWhen this she heard, the gentle maid,\nCrosswise her two pale hands she laid:\n\n\"I will say an Ave Marie,\nOur Ladye sweet, in honour of thee:\n\n\"That it may please our God, thy Son,\nTo look with pity me upon;\n\n\"That grace to pass quick me be given,\nAnd wait for those I love in Heaven.\"\n\nThe Ave Marie was hardly said,\nWhen gently sank her gentle head:\n\nThe pale head sank, no more to rise:\nThe eyelids closed upon the eyes.\n\nJust then beyond the court-yard pale\nWas heard to sing the nightingale:\n\n\"The happiest lot from life they bring,\nThe young whom death takes in the spring.\n\n\"Happy the young whose biers are strown\nWith spring-flowers, fair and freshly blown.\"","note":"A Breton song for a young girl who dies in May, her bier strewn with fresh flowers; sung in Cornouaille.","voice":"brian","source":{"name":"Ballads and Songs of Brittany, translated by Tom Taylor from the Barzaz Breiz (1865)","url":"https://archive.org/details/balladssongsofbr00lavi/page/161/mode/1up"},"rights":"pd","pd":"published 1865; Taylor died 1880"},{"id":"celtx-hyde-weakly-i-go","title":"Weakly I Go","by":"Traditional (Irish)","tr":"Douglas Hyde","year":1906,"trad":["celtic","christian","catholic"],"denom":["irish"],"type":"prayer","occasion":["forgiveness","daily"],"text":"Weakly I go from the load within,\nDeeply repenting with woe my sin.\nI acknowledge the faith of my God this day\nWith love from my heart and with hope alway,\nFrom the foot of Thy cross I call to Thee\nO Jesus Lord, bow down to me.","note":"A short prayer said during Mass in Donegal and Longford, turning a heavy heart toward the cross.","voice":"brian","source":{"name":"The Religious Songs of Connacht, vol. 2, Douglas Hyde (1906)","url":"https://archive.org/details/religioussongsof02hydeiala/page/5/mode/1up"},"rights":"pd","pd":"published 1906; public domain in the United States by publication date (Hyde died 1949)"},{"id":"celtx-hyde-i-bestow-my-soul","title":"I Bestow Thee My Soul","by":"Traditional (Irish)","tr":"Douglas Hyde","year":1906,"trad":["celtic","christian","catholic"],"denom":["irish"],"type":"prayer","occasion":["dying","comfort"],"text":"And let it not fall out of Thy control,\nBear witness O Blessed Virgin Mary\nIn the hands of thy Son do I lay my soul,\nCountenance brighter than the sun\nShield me from pain when the race is run.","note":"A prayer said during Mass in Galway, placing the soul in the hands of Christ.","voice":"brian","source":{"name":"The Religious Songs of Connacht, vol. 2, Douglas Hyde (1906)","url":"https://archive.org/details/religioussongsof02hydeiala/page/5/mode/1up"},"rights":"pd","pd":"published 1906; public domain in the United States by publication date (Hyde died 1949)"},{"id":"celtx-hyde-marys-ortha","title":"Mary's Prayer of Peace","by":"Traditional (Irish)","tr":"Douglas Hyde","year":1906,"trad":["celtic","christian","catholic"],"denom":["irish"],"type":"prayer","occasion":["dying","peace"],"text":"O Mary mother of our king\nMake with thy blessed Son, my peace,\nCountenance brighter than the sky\nLet me not sigh without release.\n\nAnd heaven henceforth is my only goal,\nBear witness O Blessed Virgin Mary\nThat I lay on the hands of thy Son my soul.","note":"A Connemara prayer asking Mary to make peace with her Son and to witness the soul given into his hands.","voice":"brian","source":{"name":"The Religious Songs of Connacht, vol. 2, Douglas Hyde (1906)","url":"https://archive.org/details/religioussongsof02hydeiala/page/7/mode/1up"},"rights":"pd","pd":"published 1906; public domain in the United States by publication date (Hyde died 1949)"},{"id":"celtx-hyde-sacraments-grace","title":"The Sacrament's Grace","by":"Traditional (Irish)","tr":"Douglas Hyde","year":1906,"trad":["celtic","christian","catholic"],"denom":["irish"],"type":"prayer","occasion":["daily","forgiveness"],"text":"The sacrament's grace\nThou hast made and willed,\nMay my heart in its place\nWith that grace be filled.\n\nThou hast forgiven\nThousands of souls earned by thee,\nLet not my soul\nFor its sin and its shame be spurned by thee.","note":"Said in Galway when the priest raises the chalice at Mass.","voice":"brian","source":{"name":"The Religious Songs of Connacht, vol. 2, Douglas Hyde (1906)","url":"https://archive.org/details/religioussongsof02hydeiala/page/7/mode/1up"},"rights":"pd","pd":"published 1906; public domain in the United States by publication date (Hyde died 1949)"},{"id":"celtx-hyde-king-of-friday","title":"O King of the Friday","by":"Traditional (Irish)","tr":"Douglas Hyde","year":1906,"trad":["celtic","christian","catholic"],"denom":["irish"],"type":"prayer","occasion":["evening","comfort"],"text":"O King of the Friday\nWhose limbs were stretched on the cross,\nO Lord who didst suffer\nThe bruises, the wounds, the loss,\n\nWe stretch ourselves\nBeneath the shield of thy might,\nMay some fruit from the tree of thy passion\nFall on us this night!","note":"A small night prayer to Christ of Good Friday, asking that fruit from the tree of his passion fall on us.","voice":"brian","source":{"name":"The Religious Songs of Connacht, vol. 2, Douglas Hyde (1906)","url":"https://archive.org/details/religioussongsof02hydeiala/page/7/mode/1up"},"rights":"pd","pd":"published 1906; public domain in the United States by publication date (Hyde died 1949)"},{"id":"celtx-hyde-will-of-god","title":"The Will of God","by":"Traditional (Irish)","tr":"Douglas Hyde","year":1906,"trad":["celtic","christian","catholic"],"denom":["irish"],"type":"litany","occasion":["morning","daily"],"text":"The will of God be done by us,\nThe law of God be kept by us,\nOur evil will controlled by us,\nOur tongue in check be held by us,\nRepentance timely made by us,\nChrist's passion understood by us,\nEach sinful crime be shunned by us,\nMuch on the End be mused by us,\nAnd Death be blessed found by us.\n\nWith Angels' music heard by us,\nAnd God's high praises sung to us\nFor ever and for aye.","note":"A Connemara morning prayer, each line ending with us, that closes with the music of the angels.","voice":"brian","source":{"name":"The Religious Songs of Connacht, vol. 2, Douglas Hyde (1906)","url":"https://archive.org/details/religioussongsof02hydeiala/page/13/mode/1up"},"rights":"pd","pd":"published 1906; public domain in the United States by publication date (Hyde died 1949)"},{"id":"celtx-hyde-help-and-friends","title":"Help and Friends","by":"Traditional (Irish)","tr":"Douglas Hyde","year":1906,"trad":["celtic","christian","catholic"],"denom":["irish"],"type":"prayer","occasion":["morning","evening","dying"],"text":"Help for us, friends for us, help and God's graces,\nHelp I am asking in all bad places,\nMay the Sacrament \"Penance\" make bright our faces,\nAnd Mary our Lady protect us and grace us.\n\nJesus, Father, Lamb, I pray\nDrive each evil thought away,\nBe with me 'till break of day,\nIn my sleep and on my way.\n\nWhen the hour of hours shall sound\nJesus be within me found.","note":"A Clare morning prayer asking for help, friends, and the company of Jesus at the hour of hours.","voice":"brian","source":{"name":"The Religious Songs of Connacht, vol. 2, Douglas Hyde (1906)","url":"https://archive.org/details/religioussongsof02hydeiala/page/17/mode/1up"},"rights":"pd","pd":"published 1906; public domain in the United States by publication date (Hyde died 1949)"},{"id":"celtx-hyde-gods-angels","title":"God's Angels","by":"Traditional (Irish)","tr":"Douglas Hyde","year":1906,"trad":["celtic","christian","catholic"],"denom":["irish"],"type":"prayer","occasion":["morning","daily"],"text":"God's angels be our company\nAnd save us while we live,\nMay God and holy Mary,\nAnd Columcille protect us,\nAnd save us until eve.","note":"A sweet morning prayer from Aran asking the angels, Mary, and Columcille to keep us till evening.","voice":"brian","source":{"name":"The Religious Songs of Connacht, vol. 2, Douglas Hyde (1906)","url":"https://archive.org/details/religioussongsof02hydeiala/page/17/mode/1up"},"rights":"pd","pd":"published 1906; public domain in the United States by publication date (Hyde died 1949)"},{"id":"celtx-hyde-may-we-behold","title":"May We Behold","by":"Traditional (Irish)","tr":"Douglas Hyde","year":1906,"trad":["celtic","christian","catholic"],"denom":["irish"],"type":"prayer","occasion":["dying","hope"],"text":"May we see God's countenance\nAnd perceive His gloriousness.\nAnd attain His paradise.\n\nA death of blessedness,\nPenance and clemency\nMay our poor soul have.","note":"A little Aran prayer to see the face of God and to have a blessed death.","voice":"brian","source":{"name":"The Religious Songs of Connacht, vol. 2, Douglas Hyde (1906)","url":"https://archive.org/details/religioussongsof02hydeiala/page/19/mode/1up"},"rights":"pd","pd":"published 1906; public domain in the United States by publication date (Hyde died 1949)"},{"id":"celtx-hyde-fragrant-prayer","title":"A Fragrant Prayer","by":"Traditional (Irish)","tr":"Douglas Hyde","year":1906,"trad":["celtic","christian","catholic"],"denom":["irish"],"type":"prayer","occasion":["morning","nature","gratitude"],"text":"A fragrant prayer upon the air\nMy child taught me,\nAwaken there, the morn is fair,\nThe birds sing free.\n\nNow dawns the day, awake and pray\nAnd bend the knee,\nThe Lamb who lay beneath the clay\nWas slain for thee.","note":"A Roscommon verse said on waking to the chirping of the birds.","voice":"brian","source":{"name":"The Religious Songs of Connacht, vol. 2, Douglas Hyde (1906)","url":"https://archive.org/details/religioussongsof02hydeiala/page/23/mode/1up"},"rights":"pd","pd":"published 1906; public domain in the United States by publication date (Hyde died 1949)"},{"id":"celtx-hyde-king-of-friends","title":"King of the Friends","by":"Traditional (Irish)","tr":"Douglas Hyde","year":1906,"trad":["celtic","christian","catholic"],"denom":["irish"],"type":"prayer","occasion":["morning","daily"],"text":"King of the friends,\nOur Saviour's Father art thou,\nKeep me erect\nTill evening moisten my brow.\n\nTeach and control\nLest I unto sin should bow,\nAnd save my soul\nFrom the foe who follows her now.","note":"A Mayo prayer said while rising and dressing.","voice":"brian","source":{"name":"The Religious Songs of Connacht, vol. 2, Douglas Hyde (1906)","url":"https://archive.org/details/religioussongsof02hydeiala/page/25/mode/1up"},"rights":"pd","pd":"published 1906; public domain in the United States by publication date (Hyde died 1949)"},{"id":"celtx-hyde-may-i-lie-with-god","title":"May I Lie With God","by":"Traditional (Irish)","tr":"Douglas Hyde","year":1906,"trad":["celtic","christian","catholic"],"denom":["irish"],"type":"prayer","occasion":["evening","peace"],"text":"That I may lie with God, and that God may lie with me,\nThat I may not lie with the Evil, and that the Evil may not lie with me,\nThe girdle of Brigit round my middle,\nAnd the mantle of Mary round my head,\nCome O young Michael and take my hand\nAnd make my peace with the Son of the Graces.\n\nIf there be any evil-thing at all in wait for me\nI put the Son of God between myself and itself.\nFrom to-night until a year from to-night,\nAnd to-night itself,\nAnd for ever,\nAnd for aye!","note":"A night prayer from Inishmaan with the girdle of Brigit and the mantle of Mary.","voice":"brian","source":{"name":"The Religious Songs of Connacht, vol. 2, Douglas Hyde (1906)","url":"https://archive.org/details/religioussongsof02hydeiala/page/29/mode/1up"},"rights":"pd","pd":"published 1906; public domain in the United States by publication date (Hyde died 1949)"},{"id":"celtx-hyde-bed-blessing-highland","title":"The Bed Blessing","by":"Traditional (Irish)","tr":"Douglas Hyde","year":1906,"trad":["celtic","christian","catholic"],"denom":["irish"],"type":"prayer","occasion":["evening","dying"],"text":"I lie down to-night\nWith Mary and with her Son,\nWith the Mother of my King\nWho does me protect from evil-deeds.\n\nI shall not lie with the Evil\nAnd the Evil shall not lie with me.\nBut I shall lie with God,\nAnd God shall lie along with me.\n\nThe right hand of God under my head,\nThe girdle of the Nine Angels with me\nFrom the top of my head\nTo the skin of my foot-soles.\n\nI pray Peter, I pray Paul,\nI pray Mary Virgin and her Son,\nI pray the Twelve Apostles\nThey, of their leave, I may not go die.\n\nO God and O Mary of glory,\nAnd O Son of the fragrant Virgin\nKeep ye me from the dark pains:\nAnd Bright Michael to meet my soul.","note":"A night prayer from Lochaber, the same blessing the Gaels kept in Ireland and Scotland alike.","voice":"brian","source":{"name":"The Religious Songs of Connacht, vol. 2, Douglas Hyde (1906)","url":"https://archive.org/details/religioussongsof02hydeiala/page/31/mode/1up"},"rights":"pd","pd":"published 1906; public domain in the United States by publication date (Hyde died 1949)"},{"id":"celtx-hyde-fold-of-night","title":"Whether I Sit or Whether I Lie","by":"Traditional (Irish)","tr":"Douglas Hyde","year":1906,"trad":["celtic","christian","catholic"],"denom":["irish"],"type":"prayer","occasion":["evening","peace"],"text":"Whether I sit or whether I lie\nOr whether I slumber deep,\nBe my guardian, be my keeper,\nWatch me through my sleep.\n\nCome, O Virgin, and take my hand,\nAnd make my peace with Thy Son, and see\nThat no evil spirit beside me stand,\nThe King of Grace between it and me!","note":"A Mayo night prayer asking the Virgin to keep watch through sleep.","voice":"brian","source":{"name":"The Religious Songs of Connacht, vol. 2, Douglas Hyde (1906)","url":"https://archive.org/details/religioussongsof02hydeiala/page/37/mode/1up"},"rights":"pd","pd":"published 1906; public domain in the United States by publication date (Hyde died 1949)"},{"id":"celtx-hyde-right-side","title":"I Lay Me Down on My Right Side","by":"Traditional (Irish)","tr":"Douglas Hyde","year":1906,"trad":["celtic","christian","catholic"],"denom":["irish"],"type":"prayer","occasion":["evening"],"text":"I lay me down on my right side,\nOn my left side me to place,\nI turn my back on the Evil Man\nAnd I face to God my face.","note":"A small night rann from Connemara.","voice":"brian","source":{"name":"The Religious Songs of Connacht, vol. 2, Douglas Hyde (1906)","url":"https://archive.org/details/religioussongsof02hydeiala/page/41/mode/1up"},"rights":"pd","pd":"published 1906; public domain in the United States by publication date (Hyde died 1949)"},{"id":"celtx-hyde-blessed-virgin-candle","title":"Blessed Virgin","by":"Traditional (Irish)","tr":"Douglas Hyde","year":1906,"trad":["celtic","christian","catholic"],"denom":["irish"],"type":"prayer","occasion":["dying","evening"],"text":"Blessed Virgin, God's own Mother,\nShining light set up on high,\nCandle blazing in the heavens,\nBe with me the day I die.","note":"A night rann from Inishmaan to Mary, the candle blazing in the heavens.","voice":"brian","source":{"name":"The Religious Songs of Connacht, vol. 2, Douglas Hyde (1906)","url":"https://archive.org/details/religioussongsof02hydeiala/page/45/mode/1up"},"rights":"pd","pd":"published 1906; public domain in the United States by publication date (Hyde died 1949)"},{"id":"celtx-hyde-confession-angels","title":"I Make My Confession","by":"Traditional (Irish)","tr":"Douglas Hyde","year":1906,"trad":["celtic","christian","catholic"],"denom":["irish"],"type":"prayer","occasion":["evening","forgiveness"],"text":"I make my confession\nUnto God overhead,\nWith the Cross of the Angels\nI lie on this bed.\n\nOne drop out of heaven\nShed down on this heart,\nThat shall banish for ever\nThe sin and the smart.","note":"A night prayer, one drop out of heaven to wash the heart clean.","voice":"brian","source":{"name":"The Religious Songs of Connacht, vol. 2, Douglas Hyde (1906)","url":"https://archive.org/details/religioussongsof02hydeiala/page/43/mode/1up"},"rights":"pd","pd":"published 1906; public domain in the United States by publication date (Hyde died 1949)"},{"id":"celtx-hyde-save-this-fire","title":"I Save This Fire To-night","by":"Traditional (Irish)","tr":"Douglas Hyde","year":1906,"trad":["celtic","christian","catholic"],"denom":["irish"],"type":"blessing","occasion":["evening","home"],"text":"As I save this fire to-night\nEven so may Christ save me,\nOn the top of the house let Mary\nLet Bride in its middle be.\n\nLet eight of the mightiest angels\nRound the throne of the Trinity\nProtect this house and its people\nTill the dawn of the day shall be.","note":"Said at night while raking the coals of the hearth to keep the seed of the fire alive till morning.","voice":"brian","source":{"name":"The Religious Songs of Connacht, vol. 2, Douglas Hyde (1906)","url":"https://archive.org/details/religioussongsof02hydeiala/page/47/mode/1up"},"rights":"pd","pd":"published 1906; public domain in the United States by publication date (Hyde died 1949)"},{"id":"celtx-hyde-journey","title":"A Prayer Before a Journey","by":"Traditional (Irish)","tr":"Douglas Hyde","year":1906,"trad":["celtic","christian","catholic"],"denom":["irish"],"type":"prayer","occasion":["blessing","hope"],"text":"In the name of the Father, with victory\nAnd of the Son who suffered the pain,\nThat Mary and her Son may be with me on my travel.\n\nO Mary meet me at the port\nDo not let my soul go by thee,\nGreat is my fear at thy Son.\n\nIn the communion of the saints may we be,\nListening to the voices of the angels,\nAnd praising the Son of God for ever and ever.","note":"Said in Connacht when setting out on the road.","voice":"brian","source":{"name":"The Religious Songs of Connacht, vol. 2, Douglas Hyde (1906)","url":"https://archive.org/details/religioussongsof02hydeiala/page/55/mode/1up"},"rights":"pd","pd":"published 1906; public domain in the United States by publication date (Hyde died 1949)"},{"id":"celtx-hyde-right-hand-angel","title":"I Pray God's Right-hand Angel","by":"Traditional (Irish)","tr":"Douglas Hyde","year":1906,"trad":["celtic","christian","catholic"],"denom":["irish"],"type":"prayer","occasion":["daily","peace"],"text":"I pray the Right-hand Angel of God\nThat he may put me on the best-way for me,\nI pray for God's sake\nThe Left-hand Spirits\nAll of them, to let me be.","note":"A short prayer for the right road, asking God's right-hand angel to lead the way.","voice":"brian","source":{"name":"The Religious Songs of Connacht, vol. 2, Douglas Hyde (1906)","url":"https://archive.org/details/religioussongsof02hydeiala/page/57/mode/1up"},"rights":"pd","pd":"published 1906; public domain in the United States by publication date (Hyde died 1949)"},{"id":"celtx-hyde-bed-dan","title":"The Bed Dan","by":"Traditional (Irish)","tr":"Douglas Hyde","year":1906,"trad":["celtic","christian","catholic"],"denom":["irish"],"type":"prayer","occasion":["evening","forgiveness","dying"],"text":"I stretch in this bed\nAs I shall stretch in the tomb.\nA hard confession I make to Thee.\n\nO God, absolution I am asking of Thee\nFor the evil-sayings of my mouth,\nFor the evil-thinkings of my heart.\n\nEverything that I have said that was not true.\nEverything that I have promised and have not fulfilled,\nBetween Thy two hands.\n\nO Blessed Virgin,\nThe three angels highest in heaven,\nMay they be protecting my soul\nNow and to-night and for ever,\nAnd at the hour of my death. Amen.","note":"A Mayo night prayer of honest confession, placing the soul between the two hands of the Son of God.","voice":"brian","source":{"name":"The Religious Songs of Connacht, vol. 2, Douglas Hyde (1906)","url":"https://archive.org/details/religioussongsof02hydeiala/page/203/mode/1up"},"rights":"pd","pd":"published 1906; public domain in the United States by publication date (Hyde died 1949)"},{"id":"celtx-hyde-night-prayer-brigid","title":"A Night Prayer","by":"Traditional (Irish)","tr":"Douglas Hyde","year":1906,"trad":["celtic","christian","catholic"],"denom":["irish"],"type":"prayer","occasion":["evening","dying"],"text":"I shall stretch myself down on this bed\nAs the Son of God was stretched upon the cross.\nThe mantle of Brigid to be for a scapular on me.\n\nThe friend of my soul to obtain the heaven.\nO Jesus Christ who wast crucified upon the cross,\nWho didst suffer the hundreds and the thousands of wounds,\nBanish every evil\nThat is spying for me to-night,\nWith regard to soul and body,\nNow and at the hour of my death. Amen.","note":"A night prayer with the mantle of Brigid around the one who sleeps.","voice":"brian","source":{"name":"The Religious Songs of Connacht, vol. 2, Douglas Hyde (1906)","url":"https://archive.org/details/religioussongsof02hydeiala/page/205/mode/1up"},"rights":"pd","pd":"published 1906; public domain in the United States by publication date (Hyde died 1949)"},{"id":"celtx-hyde-glory-to-father","title":"Glory to Father and to Son","by":"Traditional (Irish)","tr":"Douglas Hyde","year":1906,"trad":["celtic","christian","catholic"],"denom":["irish"],"type":"hymn","occasion":["daily","gratitude","dying"],"text":"Glory to Father and to Son,\nGlory to God most holy,\nGlory to Him who bore the cross,\nAnd bought the nations wholly.\n\nAnd glory to our guiding star,\nTo Mary pure and lowly.\nAll heaven adorning,\nBoth evening and morning.\n\nCome to me, guide me,\nAnd save me from fears,\nAnd make me repentant\nAnd wash me with tears,\nAnd lead me to heaven\nWhen spent are my years.","note":"A song of glory from Inishmaan that turns to Mary, the maiden of brightness, for guidance all one's years.","voice":"brian","source":{"name":"The Religious Songs of Connacht, vol. 2, Douglas Hyde (1906)","url":"https://archive.org/details/religioussongsof02hydeiala/page/205/mode/1up"},"rights":"pd","pd":"published 1906; public domain in the United States by publication date (Hyde died 1949)"},{"id":"celtx-hyde-chapel-prayer","title":"The Chapel Prayer","by":"Traditional (Irish)","tr":"Douglas Hyde","year":1906,"trad":["celtic","christian","catholic"],"denom":["irish"],"type":"prayer","occasion":["daily"],"text":"I salute thee O Church of God,\nAnd mayest thou thyself salute me.\nHoping that the Twelve Apostles might be\nPraying for myself to-day.\n\nI lower myself on my right knee to the High King,\nAnd on my left knee to the Holy Spirit,\nHoping that I might raise\nAll who are before me and behind me\nFrom the flag of the pains,\nAnd Amen after it.","note":"Said on entering the church, kneeling on the right knee and on the left.","voice":"brian","source":{"name":"The Religious Songs of Connacht, vol. 2, Douglas Hyde (1906)","url":"https://archive.org/details/religioussongsof02hydeiala/page/211/mode/1up"},"rights":"pd","pd":"published 1906; public domain in the United States by publication date (Hyde died 1949)"},{"id":"celtx-hyde-leaving-chapel","title":"On Leaving the Chapel","by":"Traditional (Irish)","tr":"Douglas Hyde","year":1906,"trad":["celtic","christian","catholic"],"denom":["irish"],"type":"prayer","occasion":["daily","blessing"],"text":"Farewell, O Mary;\nO Christ, farewell,\nAnd keep my soul\nTill I come again.\n\nFarewell to thee, O House of God,\nMay not thy blessings wither,\nAnd may God's grace not part from us\nTill we again come hither.","note":"Two small verses said at the church door on the way home, from Cork and from Galway.","voice":"brian","source":{"name":"The Religious Songs of Connacht, vol. 2, Douglas Hyde (1906)","url":"https://archive.org/details/religioussongsof02hydeiala/page/213/mode/1up"},"rights":"pd","pd":"published 1906; public domain in the United States by publication date (Hyde died 1949)"},{"id":"celtx-hyde-when-your-eyes","title":"When Your Eyes Shall Be Closing","by":"Traditional (Irish)","tr":"Douglas Hyde","year":1906,"trad":["celtic","christian","catholic"],"denom":["irish"],"type":"prayer","occasion":["dying","comfort","funeral"],"text":"When your eyes shall be closing, your mouth be opening,\nAnd your senses be slipping away,\nWhen your heart shall grow cold and your limbs be old,\nGod comfort your soul that day.\n\nAnd John the Baptist, to him I pray,\nAnd to every saint that is high in heaven,\nTo save my soul that day.\n\nThe Virgin shall come, and her white arms spreading,\n\"Repent of your sins,\" herself shall say,\nIn the court of heaven, your only comfort\nMust come from her that day.","note":"An Inishmaan prayer for the last hour, when the senses slip away and God comforts the soul.","voice":"brian","source":{"name":"The Religious Songs of Connacht, vol. 2, Douglas Hyde (1906)","url":"https://archive.org/details/religioussongsof02hydeiala/page/215/mode/1up"},"rights":"pd","pd":"published 1906; public domain in the United States by publication date (Hyde died 1949)"},{"id":"celtx-hyde-i-rise-up","title":"I Rise Up With God","by":"Traditional (Irish)","tr":"Douglas Hyde","year":1906,"trad":["celtic","christian","catholic"],"denom":["irish"],"type":"prayer","occasion":["morning","daily"],"text":"I rise up with God,\nMay God rise up with me,\nGod's hand round about me,\nSitting and lying,\nAnd rising of me.","note":"A small morning rann for the moment of rising.","voice":"brian","source":{"name":"The Religious Songs of Connacht, vol. 2, Douglas Hyde (1906)","url":"https://archive.org/details/religioussongsof02hydeiala/page/217/mode/1up"},"rights":"pd","pd":"published 1906; public domain in the United States by publication date (Hyde died 1949)"},{"id":"celtx-hyde-four-corners","title":"Four Corners to My Bed","by":"Traditional (Irish)","tr":"Douglas Hyde","year":1906,"trad":["celtic","christian","catholic"],"denom":["irish"],"type":"prayer","occasion":["evening","dying"],"text":"Four corners to my bed,\nFour angels round it spread.\nIf I die within the night\nGod receive me into light.","note":"A bedtime rann for children and grown-ups alike.","voice":"brian","source":{"name":"The Religious Songs of Connacht, vol. 2, Douglas Hyde (1906)","url":"https://archive.org/details/religioussongsof02hydeiala/page/217/mode/1up"},"rights":"pd","pd":"published 1906; public domain in the United States by publication date (Hyde died 1949)"},{"id":"celtx-hyde-four-posts","title":"Four Posts Around My Bed","by":"Traditional (Irish)","tr":"Douglas Hyde","year":1906,"trad":["celtic","christian","catholic"],"denom":["irish"],"type":"prayer","occasion":["evening"],"text":"Four posts around my bed,\nFour angels have it spread,\nMathew, Mark, Luke, and John,\nKeep me, O God, till the day shall dawn.","note":"The Aran form of the old bedtime verse naming the four Gospel writers.","voice":"brian","source":{"name":"The Religious Songs of Connacht, vol. 2, Douglas Hyde (1906)","url":"https://archive.org/details/religioussongsof02hydeiala/page/217/mode/1up"},"rights":"pd","pd":"published 1906; public domain in the United States by publication date (Hyde died 1949)"},{"id":"celtx-hyde-to-saint-patrick","title":"To Saint Patrick","by":"Traditional (Irish)","tr":"Douglas Hyde","year":1906,"trad":["celtic","christian","catholic"],"denom":["irish"],"type":"prayer","occasion":["dying","hope"],"text":"O Patrick in the Paradise\nOf God on high,\nWho lookest on the poor man\nWith a gracious eye.\n\nSee me come before thee\nWho am weak and bare,\nO help me into Paradise\nTo find thee there.","note":"A little song in honour of Saint Patrick from Mayo, asking his help into Paradise.","voice":"brian","source":{"name":"The Religious Songs of Connacht, vol. 2, Douglas Hyde (1906)","url":"https://archive.org/details/religioussongsof02hydeiala/page/229/mode/1up"},"rights":"pd","pd":"published 1906; public domain in the United States by publication date (Hyde died 1949)"},{"id":"celtx-hyde-lord-who-didst-suffer","title":"O Lord, Who Didst Suffer","by":"Traditional (Irish)","tr":"Douglas Hyde","year":1906,"trad":["celtic","christian","catholic"],"denom":["irish"],"type":"prayer","occasion":["comfort"],"text":"O Lord, who didst suffer Thy tortures for me,\nTorn with iron from the head to the knee,\nWhose feet and whose hands were nailed to the tree,\nHelp, Lord! I come seeking protection of Thee.","note":"A four line prayer to Christ of the cross, asking for his protection.","voice":"brian","source":{"name":"The Religious Songs of Connacht, vol. 2, Douglas Hyde (1906)","url":"https://archive.org/details/religioussongsof02hydeiala/page/257/mode/1up"},"rights":"pd","pd":"published 1906; public domain in the United States by publication date (Hyde died 1949)"},{"id":"celtx-hyde-we-do-obeisance","title":"We Do Obeisance","by":"Traditional (Irish)","tr":"Douglas Hyde","year":1906,"trad":["celtic","christian","catholic"],"denom":["irish"],"type":"prayer","occasion":["forgiveness","daily"],"text":"We do obeisance and bow down in the name of Jesus Christ, asking forgiveness and pardon for our sins.\nWe are asking help and assistance of Thee\nTo put before us the good of our souls,\nBy Thy not giving anything at all\nIn this world to us\nThat might take our share\nOf the eternal glory of the heavens from us,\nBut rather each and every thing\nThat shall most make for the prosperity\nAnd good of our souls.","note":"A prayer to receive whatever most makes for the good of the soul.","voice":"brian","source":{"name":"The Religious Songs of Connacht, vol. 2, Douglas Hyde (1906)","url":"https://archive.org/details/religioussongsof02hydeiala/page/355/mode/1up"},"rights":"pd","pd":"published 1906; public domain in the United States by publication date (Hyde died 1949)"},{"id":"celtx-hyde-o-blessed-mary","title":"O Blessed Mary","by":"Traditional (Irish)","tr":"Douglas Hyde","year":1906,"trad":["celtic","christian","catholic"],"denom":["irish"],"type":"prayer","occasion":["dying"],"text":"O Blessed Mary, most high in heaven,\nWho art near to the King, as the Scripture saith,\nMay my soul be acceptable in thy presence,\nBoth now and at the hour of death.","note":"A short prayer to Mary for the present hour and the hour of death.","voice":"brian","source":{"name":"The Religious Songs of Connacht, vol. 2, Douglas Hyde (1906)","url":"https://archive.org/details/religioussongsof02hydeiala/page/357/mode/1up"},"rights":"pd","pd":"published 1906; public domain in the United States by publication date (Hyde died 1949)"},{"id":"celtx-hyde-hundred-welcomes","title":"A Hundred Welcomes","by":"Traditional (Irish)","tr":"Douglas Hyde","year":1906,"trad":["celtic","christian","catholic"],"denom":["irish"],"type":"prayer","occasion":["daily","gratitude"],"text":"A hundred welcomes to Thee, O blessed Body,\nA hundred welcomes to Thy Body that was crucified,\nA hundred welcomes to Thy Body, O Lord.\n\nO Son of God to Thee all hail,\nO Tree whose blossoms never fail,\nThy Boughs of luck perfume the gale.\n\nAs Mark and Mathew both have told us,\nIf thou art willing to accept us\nAnd hold us in Thy hand as precious,\nMercy I ask of Thee and graces\nFor me and for each who of Adam's race is,\nWhom God and the Church have bade us pray for. Amen.","note":"A greeting to Christ in the Eucharist, the tree of ever-blooming blossoms.","voice":"brian","source":{"name":"The Religious Songs of Connacht, vol. 2, Douglas Hyde (1906)","url":"https://archive.org/details/religioussongsof02hydeiala/page/359/mode/1up"},"rights":"pd","pd":"published 1906; public domain in the United States by publication date (Hyde died 1949)"},{"id":"celtx-hyde-jesus-mary-joseph","title":"To Jesus and Mary","by":"Traditional (Irish)","tr":"Douglas Hyde","year":1906,"trad":["celtic","christian","catholic"],"denom":["irish"],"type":"prayer","occasion":["dying","daily"],"text":"To Jesus and Mary and Joseph for ever\nI offer my heart and my soul's endeavour,\nNow and at the hour of my death. Amen.","note":"A three line offering of the heart, said at any time.","voice":"brian","source":{"name":"The Religious Songs of Connacht, vol. 2, Douglas Hyde (1906)","url":"https://archive.org/details/religioussongsof02hydeiala/page/367/mode/1up"},"rights":"pd","pd":"published 1906; public domain in the United States by publication date (Hyde died 1949)"},{"id":"celtx-hyde-three-oldest","title":"May the Three Who Are Oldest","by":"Traditional (Irish)","tr":"Douglas Hyde","year":1906,"trad":["celtic","christian","catholic"],"denom":["irish"],"type":"blessing","occasion":["season","blessing","evening"],"text":"May the three who are oldest, the three who are youngest,\nIn the glory of heaven, the three who are strongest,\nMay the Father, the Son and the Spirit in one\nKeep me and guard till the year be done,\nAnd to-night itself also!","note":"A melodious little rann for the turning of the year, asking the Three to keep us till the year be done.","voice":"brian","source":{"name":"The Religious Songs of Connacht, vol. 2, Douglas Hyde (1906)","url":"https://archive.org/details/religioussongsof02hydeiala/page/367/mode/1up"},"rights":"pd","pd":"published 1906; public domain in the United States by publication date (Hyde died 1949)"},{"id":"celtx-hyde-for-the-dead","title":"For the Dead","by":"Traditional (Irish)","tr":"Douglas Hyde","year":1906,"trad":["celtic","christian","catholic"],"denom":["irish"],"type":"prayer","occasion":["funeral","grief","dying"],"text":"Three Paters, three Ave Marias and a creed,\nFor the Souls of the Dead,\nFor the soul of every person from whom we have gained\nEither little or much,\nEither with our knowledge or without our knowledge,\nOr, openly-and-publicly.\n\nIf God see a remainder of Confession unsaid,\nOr, of penance unfulfilled on their souls\nWe pray him\nTo increase their glories,\nAnd to diminish their pains;\nAnd to grant them forgiveness of their sins,\nAnd a prayer for the soul of every poor creature\nWho has, himself, no one\nTo pray on his behalf.","note":"A prayer for the souls of all from whom we have gained little or much, and for the one with no one to pray for them.","voice":"brian","source":{"name":"The Religious Songs of Connacht, vol. 2, Douglas Hyde (1906)","url":"https://archive.org/details/religioussongsof02hydeiala/page/373/mode/1up"},"rights":"pd","pd":"published 1906; public domain in the United States by publication date (Hyde died 1949)"},{"id":"celtx-hyde-milking-cow","title":"The Prayer on Milking a Cow","by":"Traditional (Irish)","tr":"Douglas Hyde","year":1906,"trad":["celtic","christian","catholic"],"denom":["irish"],"type":"blessing","occasion":["nature","blessing","daily"],"text":"The blessing of Mary, and the blessing of God,\nThe blessing of the Sun, and the Moon in her road,\nOf the Man in the East, and the Man in the West,\nAnd my blessing be with thee, and be thou blest.","note":"A Connacht blessing said at the milking, fit for blessing any creature or person.","voice":"brian","source":{"name":"The Religious Songs of Connacht, vol. 2, Douglas Hyde (1906)","url":"https://archive.org/details/religioussongsof02hydeiala/page/383/mode/1up"},"rights":"pd","pd":"published 1906; public domain in the United States by publication date (Hyde died 1949)"},{"id":"celtx-hyde-all-hail-body","title":"All Hail!","by":"Traditional (Irish)","tr":"Douglas Hyde","year":1906,"trad":["celtic","christian","catholic"],"denom":["irish"],"type":"prayer","occasion":["daily","forgiveness"],"text":"All hail to Thee, O Body of Christ,\nAll hail, O King of Heaven's lights,\nAll hail, O Holy Trinity,\nAll hail to Thee thou Right of Rights.\n\nAll hail to Thee, O flesh and blood,\nAll hail to Thee, O king of good,\nNo more be angry with my soul,\nBut wash it in Thy precious blood.\n\nNo more be angry with my soul,\nBut cleanse it by Thy gracious might,\nA hundred welcomes, God and man,\nBoth now and when the Death shall smite.","note":"A greeting to Christ, King of heaven's lights, asking mercy now and at death.","voice":"brian","source":{"name":"The Religious Songs of Connacht, vol. 2, Douglas Hyde (1906)","url":"https://archive.org/details/religioussongsof02hydeiala/page/393/mode/1up"},"rights":"pd","pd":"published 1906; public domain in the United States by publication date (Hyde died 1949)"},{"id":"celtx-hyde-all-hail-mary","title":"All Hail to Thee, Mary","by":"Traditional (Irish)","tr":"Douglas Hyde","year":1906,"trad":["celtic","christian","catholic"],"denom":["irish"],"type":"prayer","occasion":["daily","birth"],"text":"All hail to thee, Mary,\nWith grace from above.\nAnd all hail to thee, Queen,\nWho comest in love,\nAnd blessed thou art\nAmongst women, and blest\nIs thy holy child, Jesus,\nWho lay on thy breast.","note":"A short rhymed Hail Mary from Connacht.","voice":"brian","source":{"name":"The Religious Songs of Connacht, vol. 2, Douglas Hyde (1906)","url":"https://archive.org/details/religioussongsof02hydeiala/page/393/mode/1up"},"rights":"pd","pd":"published 1906; public domain in the United States by publication date (Hyde died 1949)"},{"id":"celtx-hyde-mary-mother-pray","title":"O Mary, Mother of God","by":"Traditional (Irish)","tr":"Douglas Hyde","year":1906,"trad":["celtic","christian","catholic"],"denom":["irish"],"type":"prayer","occasion":["daily","dying"],"text":"O Mary, Mother of God, I pray,\nPray thou for me throughout the day,\nAnd at the hour of our death. Amen.","note":"A three line prayer to Mary for the whole day.","voice":"brian","source":{"name":"The Religious Songs of Connacht, vol. 2, Douglas Hyde (1906)","url":"https://archive.org/details/religioussongsof02hydeiala/page/395/mode/1up"},"rights":"pd","pd":"published 1906; public domain in the United States by publication date (Hyde died 1949)"},{"id":"celtx-hyde-angel-high-born","title":"O Angel High-born","by":"Traditional (Irish)","tr":"Douglas Hyde","year":1906,"trad":["celtic","christian","catholic"],"denom":["irish"],"type":"prayer","occasion":["evening","dying"],"text":"O Angel high-born\nCome me forlorn to guard,\nTo the King who once bought me\nAnd sought me through perils hard.\n\nHold from me the demons\nWhose schemings my way have barred,\nAnd in thy safe-keeping\nBring me to God's home bright starred.","note":"A night verse asking the guardian angel to bring the soul to God's starry home.","voice":"brian","source":{"name":"The Religious Songs of Connacht, vol. 2, Douglas Hyde (1906)","url":"https://archive.org/details/religioussongsof02hydeiala/page/395/mode/1up"},"rights":"pd","pd":"published 1906; public domain in the United States by publication date (Hyde died 1949)"},{"id":"celtx-hyde-three-folds","title":"Three Folds in My Garment","by":"Traditional (Irish)","tr":"Douglas Hyde","year":1906,"trad":["celtic","christian","catholic"],"denom":["irish"],"type":"poem","occasion":["daily","nature"],"text":"Three folds in my garment, yet only one garment I bear,\nThree joints in a finger, yet only one finger is there,\nThree leaves in a shamrock, yet only one shamrock I wear.\n\nFrost, ice, and snow, these three are nothing but water,\nThree Persons in God, yet only one God is there.","note":"A melodious Connacht rann on the Trinity, drawn from a garment, a finger, a shamrock, and water.","voice":"brian","source":{"name":"The Religious Songs of Connacht, vol. 2, Douglas Hyde (1906)","url":"https://archive.org/details/religioussongsof02hydeiala/page/397/mode/1up"},"rights":"pd","pd":"published 1906; public domain in the United States by publication date (Hyde died 1949)"},{"id":"celtx-hyde-thanksgiving-communion","title":"Thanksgiving After Communion","by":"Traditional (Irish)","tr":"Douglas Hyde","year":1906,"trad":["celtic","christian","catholic"],"denom":["irish"],"type":"prayer","occasion":["gratitude","dying"],"text":"May His Body make me safer,\nHoly Wafer, deep my sigh,\nCleanse me from the stains that stain me,\nNor disdain me when I die.\n\nLord who enterest my members\nLike the embers Thou dost shine,\nTake my soul from out my bosom,\nCleanse from stain and make it Thine.\n\nGreat Creator, Lord of Graces,\nThou whose face is as the sun,\nGrand artificer of heaven,\nMake my will and Thine be one.\n\nO Creator, show me mercy,\nThou whose face is as the sun,\nAnd the body where thou lodgest\nTake to Thee when all is done.","note":"A very old thanksgiving after receiving Communion, still in the mouths of the people.","voice":"brian","source":{"name":"The Religious Songs of Connacht, vol. 2, Douglas Hyde (1906)","url":"https://archive.org/details/religioussongsof02hydeiala/page/401/mode/1up"},"rights":"pd","pd":"published 1906; public domain in the United States by publication date (Hyde died 1949)"},{"id":"celtx-hyde-king-of-world","title":"O King of the World","by":"Traditional (Irish)","tr":"Douglas Hyde","year":1906,"trad":["celtic","christian","catholic"],"denom":["irish"],"type":"prayer","occasion":["forgiveness","nature"],"text":"O King of the world,\nWho lightest the sun's bright ray,\nWho movest the rains that ripen\nThe fruit on the spray.\n\nBefore Thee I lay,\nO keep me from falling deeper\nAnd deeper away.","note":"A short prayer to the King who lights the sun and ripens the fruit.","voice":"brian","source":{"name":"The Religious Songs of Connacht, vol. 2, Douglas Hyde (1906)","url":"https://archive.org/details/religioussongsof02hydeiala/page/403/mode/1up"},"rights":"pd","pd":"published 1906; public domain in the United States by publication date (Hyde died 1949)"},{"id":"celtx-hyde-more-lasting","title":"More Lasting","by":"Traditional (Irish)","tr":"Douglas Hyde","year":1906,"trad":["celtic","all"],"denom":["irish"],"type":"poem","occasion":["funeral","grief"],"text":"More lasting is Fame than the life of men\nFor tradition then may keep it young,\nBut more lasting still is the poet's pen,\nAnd the book that speaks with undying tongue.","note":"A Gaelic verse on what outlasts a life: memory, tradition, and the written word.","voice":"brian","source":{"name":"The Religious Songs of Connacht, vol. 2, Douglas Hyde (1906)","url":"https://archive.org/details/religioussongsof02hydeiala/page/405/mode/1up"},"rights":"pd","pd":"published 1906; public domain in the United States by publication date (Hyde died 1949)"},{"id":"celtx-hyde-who-came","title":"Who Have Come Have Gone","by":"Traditional (Irish)","tr":"Douglas Hyde","year":1906,"trad":["celtic","christian","all"],"denom":["irish"],"type":"poem","occasion":["funeral","grief","hope"],"text":"Who have come have gone, who shall come must go,\nBut the graces of God shall forever flow.","note":"Two closing lines from the Religious Songs of Connacht, a gentle word for a graveside.","voice":"brian","source":{"name":"The Religious Songs of Connacht, vol. 2, Douglas Hyde (1906)","url":"https://archive.org/details/religioussongsof02hydeiala/page/407/mode/1up"},"rights":"pd","pd":"published 1906; public domain in the United States by publication date (Hyde died 1949)"},{"id":"celtx-hyde-great-mary","title":"From Great Mary","by":"Owen O'Duffy","tr":"Douglas Hyde","year":1906,"trad":["celtic","christian","catholic"],"denom":["irish"],"type":"litany","occasion":["daily","comfort","gratitude"],"text":"Good is the woman, Great Mary,\nThe mother of the High-king of the eternal hosts,\nThey are her graces which are ever full,\nA woman who put a hedge round each country.\n\nA woman to whom right inclines,\nA woman greatest in strength and power,\nA woman softest, i.e., most generous, in red gold,\nA woman by whom is quenched the anger of the king.\n\nA woman who gives sight to the blind,\nA woman who is most powerful beyond in heaven,\nA woman who has taken away my enemies from me,\nA woman who is a defence to me in every battle.","note":"A litany of praise to Mary by the Irish poet Owen O'Duffy, each line beginning A woman who.","voice":"brian","source":{"name":"The Religious Songs of Connacht, vol. 1, Douglas Hyde (1906)","url":"https://archive.org/details/religioussongsof01hydeiala/page/129/mode/1up"},"rights":"pd","pd":"published 1906; public domain in the United States by publication date (Hyde died 1949)"},{"id":"celtx-lh-ninine","title":"Ninine's Prayer","by":"Attributed to Ninine the poet","tr":"J. H. Bernard and R. Atkinson","year":1898,"trad":["celtic","christian"],"denom":["irish"],"type":"prayer","occasion":["daily","blessing"],"text":"We commemorate Saint Patrick,\nchief apostle of Ireland;\nFamous is his wonderful name,\nflame that baptized heathens.\n\nHe fought against druids\nhard of heart;\nHe cast down haughty men with the help of our Lord\nof bright heaven;\n\nHe cleansed Ireland's\nterritories, he the Great Birth.\nWe pray to Patrick, chief apostle,\nwho hath saved us to Doom's day\n\nFrom judgement by the malevolence\nof dark demons.\nGod be with me, with the prayer\nof Patrick, chief apostle!","note":"An old Irish collect for Saint Patrick, said to be by Ninine the poet or by Fiacc of Sletty.","voice":"brian","source":{"name":"The Irish Liber Hymnorum, vol. 2, translations by J. H. Bernard and R. Atkinson (1898)","url":"https://archive.org/details/irishliberhymnor02bern/page/36/mode/1up"},"rights":"pd","pd":"published 1898; Bernard died 1927 and Atkinson died 1908"},{"id":"celtx-lh-ultan-brigid","title":"Brigid, Ever-good Woman","by":"Attributed to Ultan of Ardbreccan","tr":"J. H. Bernard and R. Atkinson","year":1898,"trad":["celtic","christian"],"denom":["irish"],"type":"hymn","occasion":["blessing","hope","dying"],"text":"Brigid, ever-good woman,\nflame golden, sparkling,\nmay she bear us to the eternal kingdom,\nshe, the sun fiery, radiant!\n\nMay Brigid free us\npast crowds of demons!\nmay she win for us\nbattles over every disease!\n\nMay she extirpate in us\nthe vices of our flesh,\nshe, the branch with blossoms,\nthe mother of Jesus!\n\nThe true-virgin, dear,\nwith vast pre-eminence,\nmay we be free, at all times,\nalong with my Saint of Leinster-folk!\n\nOne of the two pillars of the Kingdom,\nalong with Patrick the pre-eminent as the other pillar\nthe vestment beyond even splendid vestments,\nthe royal Queen!\n\nMay they lie, after old age,\nour bodies, in sackcloth;\nbut with her grace may she bedew us,\nmay she free us, Brigid!","note":"The old Irish hymn to Saint Brigid, credited to Ultan of Ardbreccan or to Colum Cille in a storm at sea.","voice":"brian","source":{"name":"The Irish Liber Hymnorum, vol. 2, translations by J. H. Bernard and R. Atkinson (1898)","url":"https://archive.org/details/irishliberhymnor02bern/page/39/mode/1up"},"rights":"pd","pd":"published 1898; Bernard died 1927 and Atkinson died 1908"},{"id":"celtx-lh-sanctan","title":"Saint Sanctan's Hymn","by":"Attributed to Bishop Sanctan","tr":"J. H. Bernard and R. Atkinson","year":1898,"trad":["celtic","christian"],"denom":["irish"],"type":"prayer","occasion":["blessing","peace","comfort"],"text":"I beseech a wonderful King of angels,\nfor it is a name that is mightiest;\nto me be God for my rear, God on my left,\nGod for my van, God on my right!\n\nGod for my help, holy call,\nagainst each danger, Him I invoke!\na bridge of life let there be below me,\nbenediction of God the Father above me!\n\nLet the lofty Trinity arouse us,\neach one to whom a good death is not yet certain!\nHoly Spirit noble, strength of heaven,\nGod the Father, Mary's mighty Son!\n\nA great King who knows our offences\nLord over earth, without sin,\nto my soul for every black-sin\nlet never demons' godlessness visit me!\n\nGod with me, may He take away each toil!\nmay Christ draw up my pleadings,\nmay apostles come all around me,\nmay the Trinity of witness come to me!\n\nMay mercy come to me on earth,\nfrom Christ let not my songs be hidden!\nlet not death in its death-wail reach me,\nnor sudden death in disease befal me!\n\nMay no malignant thrust that stupefies and perplexes\nreach me without permission of the Son of God!\nMay Christ save us from every bloody death,\nfrom fire, from raging sea!\n\nFrom every death-drink, that is unsafe\nfor my body, with many terrors!\nmay the Lord each hour come to me\nagainst wind, against swift waters!\n\nI shall utter the praises of Mary's Son\nwho fights for good deeds,\nand God of the elements will reply,\nfor my tongue is a lorica for battle.\n\nIn beseeching God from the heavens\nmay my body be incessantly laborious;\nthat I may not come to horrible hell\nI beseech the King whom I have besought.\n\nBishop Sanctan a sage\nsoldier, angel famous pure-white,\nmay he make free my body on earth,\nmay he make holy my soul towards heaven!\n\nMay there be a prayer with thee for me, O Mary!\nMay heaven's King be merciful to us\nagainst wound, danger and peril!\nO Christ, on Thy protection rest we!\n\nI beseech the King free, everlasting\nOnly Son of God, to watch over us;\nmay He protect me against sharp dangers,\nHe, the Child that was born in Bethlehem.","note":"A lorica, or breastplate prayer, from early Ireland: God behind, before, and on every side.","voice":"brian","source":{"name":"The Irish Liber Hymnorum, vol. 2, translations by J. H. Bernard and R. Atkinson (1898)","url":"https://archive.org/details/irishliberhymnor02bern/page/47/mode/1up"},"rights":"pd","pd":"published 1898; Bernard died 1927 and Atkinson died 1908"},{"id":"celtx-lh-mael-isu","title":"From the Hymn of Mael-Isu: The Holy Spirit Around Us","by":"Mael-Isu Ua Brolchain","tr":"J. H. Bernard and R. Atkinson","year":1898,"trad":["celtic","christian"],"denom":["irish"],"type":"hymn","occasion":["blessing","healing","daily"],"text":"The Holy Spirit around us,\nin us and with us,\nthe Holy Spirit to us,\nmay it come, O Christ, suddenly!\n\nThe Holy Spirit to inhabit\nour body and our soul,\nto protect us speedily\nagainst peril, against diseases!\n\nAgainst demons, against sins,\nagainst hell with many evils,\nO Jesus, may it sanctify us,\nmay Thy Spirit free us!","note":"A short Irish hymn of the eleventh century asking the Holy Spirit to dwell in body and soul.","voice":"brian","source":{"name":"The Irish Liber Hymnorum, vol. 2, translations by J. H. Bernard and R. Atkinson (1898)","url":"https://archive.org/details/irishliberhymnor02bern/page/52/mode/1up"},"rights":"pd","pd":"published 1898; Bernard died 1927 and Atkinson died 1908"},{"id":"celtx-welsh-friend-in-jordan","title":"A Friend in Jordan","by":"Welsh hymn, author not named in the source","tr":"Joseph Morris","year":1854,"trad":["celtic","christian"],"denom":["welsh"],"type":"hymn","occasion":["dying","comfort","hope"],"text":"Who amid the swelling billows\nCan sustain my sinking head?\nNone but that divine Redeemer,\nWho upon the cross hath bled.\nIf He through the stormy current\nO'er the wave my head will bear,\nIf a gracious look vouchsafe me,\nI will praise Him even there.","note":"A Welsh hymn for the crossing of the river, trusting the one who bears our head above the waves.","voice":"brian","source":{"name":"Favourite Welsh Hymns, translated by Joseph Morris (1854)","url":"https://www.gutenberg.org/ebooks/30370"},"rights":"pd","pd":"published 1854; Morris translated these in 1854"},{"id":"celtx-welsh-heavenly-adoration","title":"Heavenly Adoration","by":"Welsh hymn, author not named in the source","tr":"Joseph Morris","year":1854,"trad":["celtic","christian"],"denom":["welsh"],"type":"hymn","occasion":["gratitude","celebration"],"text":"Angelic throngs unnumbered,\nAs dawn's bright drops of dew,\nPresent their crowns before HIM\nWith praises ever new:\nBut saints and angels blending\nTheir songs above the sun,\nCan ne'er express the glories\nOf God with man made one.","note":"A Welsh hymn of praise, with angels as many as the drops of dawn dew.","voice":"brian","source":{"name":"Favourite Welsh Hymns, translated by Joseph Morris (1854)","url":"https://www.gutenberg.org/ebooks/30370"},"rights":"pd","pd":"published 1854; Morris translated these in 1854"},{"id":"celtx-welsh-the-unseen","title":"The Unseen","by":"Welsh hymn, author not named in the source","tr":"Joseph Morris","year":1854,"trad":["celtic","christian"],"denom":["welsh"],"type":"hymn","occasion":["daily","gratitude"],"text":"Though unseen, O Lord, I love Thee,\nWondrous is thy saving might,\nThus to wean my soul so sweetly\nFrom its sinful chief delight:\nMore Thou didst in one short instant\nThan a world could e'er have done,\nWinning Thee a happy dwelling\nIn this sterile heart of stone.","note":"A Welsh hymn of love for the unseen Lord who wins a home in the heart.","voice":"brian","source":{"name":"Favourite Welsh Hymns, translated by Joseph Morris (1854)","url":"https://www.gutenberg.org/ebooks/30370"},"rights":"pd","pd":"published 1854; Morris translated these in 1854"},{"id":"celtx-welsh-jubilee","title":"Jubilee","by":"Welsh hymn, author not named in the source","tr":"Joseph Morris","year":1854,"trad":["celtic","christian"],"denom":["welsh"],"type":"hymn","occasion":["hope","dying"],"text":"I am through the lone night waiting,\nFor the dawning of the day,\nWhen my prison door is opened,\nWhen my fetters fall away.\nO come quickly,\nHappy day of Jubilee!\n\nLet me still be meekly wakeful,\nTrusting that to all my woes,\nBy thy mighty hand, Redeemer,\nShall be given a speedy close:\nKeep me watching,\nFor the joyful Jubilee.","note":"A Welsh hymn of waiting through the long night for the dawning of the day.","voice":"brian","source":{"name":"Favourite Welsh Hymns, translated by Joseph Morris (1854)","url":"https://www.gutenberg.org/ebooks/30370"},"rights":"pd","pd":"published 1854; Morris translated these in 1854"},{"id":"celtx-welsh-looking-beyond","title":"Looking Beyond","by":"Welsh hymn, author not named in the source","tr":"Joseph Morris","year":1854,"trad":["celtic","christian"],"denom":["welsh"],"type":"hymn","occasion":["dying","hope","evening"],"text":"I look beyond the distant hills,\nMy risen Lord to see:\nO come, Beloved, ere the dusk,\nMy sun doth set on me!\n\nMethinks that were my feet released\nFrom these afflicting chains,\nI would but sing of Calvary,\nNor think of all my pains.\n\nI long for thy divine abode,\nWhere sinless myriads dwell,\nWho ceaseless sing thy boundless love,\nAnd all thy glories tell.","note":"A Welsh hymn of looking beyond the distant hills toward home, often sung near the end of life.","voice":"brian","source":{"name":"Favourite Welsh Hymns, translated by Joseph Morris (1854)","url":"https://www.gutenberg.org/ebooks/30370"},"rights":"pd","pd":"published 1854; Morris translated these in 1854"},{"id":"celtx-welsh-dawn","title":"Dawn","by":"Welsh hymn, author not named in the source","tr":"Joseph Morris","year":1854,"trad":["celtic","christian"],"denom":["welsh"],"type":"hymn","occasion":["hope","morning"],"text":"It shall not long remain,\nThis dark tempestuous night;\nNot long doth Christ ordain,\nTo bear the cross, and fight:\nBehold the herald Dawn appear,\nAuspicious morn is drawing near.","note":"A short Welsh hymn: the night will soon be gone and the herald dawn appears.","voice":"brian","source":{"name":"Favourite Welsh Hymns, translated by Joseph Morris (1854)","url":"https://www.gutenberg.org/ebooks/30370"},"rights":"pd","pd":"published 1854; Morris translated these in 1854"},{"id":"celtx-welsh-far-better","title":"Far Better","by":"Welsh hymn, author not named in the source","tr":"Joseph Morris","year":1854,"trad":["celtic","christian"],"denom":["welsh"],"type":"hymn","occasion":["funeral","grief","dying"],"text":"Many dear ones are departed\nTo the grave's dark silent land:\nI shall soon receive the summons\nThere to lie amid the band;\nWhere they hear not\nAny more sad earth's complaints.\n\nBlest are they who have expired\nIn the Lord, supremely blest!\nIn the port so oft desired\nThey for ever safely rest.\nHow much better,\nThere to sing than sigh with us!","note":"A Welsh funeral hymn remembering the dear ones who now rest safely in port.","voice":"brian","source":{"name":"Favourite Welsh Hymns, translated by Joseph Morris (1854)","url":"https://www.gutenberg.org/ebooks/30370"},"rights":"pd","pd":"published 1854; Morris translated these in 1854"},{"id":"celtx-welsh-the-saved","title":"The Saved","by":"Welsh hymn, author not named in the source","tr":"Joseph Morris","year":1854,"trad":["celtic","christian"],"denom":["welsh"],"type":"hymn","occasion":["funeral","hope"],"text":"I see a myriad saved,\nWho once were faint as I;\nNow they have climbed the rocky steeps,\nAnd reign with Christ on high.\nThey sing on yonder side,\nFrom doubt and sorrow free,\nThe praises of the bleeding Lamb,\nThe song of Calvary.","note":"A Welsh hymn seeing the great company who once were faint and now sing on the far side.","voice":"brian","source":{"name":"Favourite Welsh Hymns, translated by Joseph Morris (1854)","url":"https://www.gutenberg.org/ebooks/30370"},"rights":"pd","pd":"published 1854; Morris translated these in 1854"},{"id":"celtx-welsh-endless-praise","title":"Endless Praise","by":"Welsh hymn, author not named in the source","tr":"Joseph Morris","year":1854,"trad":["celtic","christian"],"denom":["welsh"],"type":"hymn","occasion":["funeral","celebration","hope"],"text":"But begun will be the singing\nUnto Jesus round His throne,\nBy the saved when tardy ages\nWith their songs and joys are flown:\nAnd for ever,\nShall the golden harps resound.\n\nThere shall I rehearse the story,\nHow a weakling faint and worn,\nWas o'er rocks and through deep waters,\nTo eternal glory borne:\nJesus wholly,\nShall absorb the songs of heaven.","note":"A Welsh hymn of the singing that only begins when the ages are done.","voice":"brian","source":{"name":"Favourite Welsh Hymns, translated by Joseph Morris (1854)","url":"https://www.gutenberg.org/ebooks/30370"},"rights":"pd","pd":"published 1854; Morris translated these in 1854"},{"id":"celtx-welsh-approaching-land","title":"Approaching Land","by":"William Williams, Pantycelyn","tr":"Joseph Morris","year":1854,"trad":["celtic","christian"],"denom":["welsh"],"type":"hymn","occasion":["dying","hope","funeral"],"text":"Here I am a passing stranger,\nFar away my native land;\nO'er the wide and stormy ocean,\nWhere lies Canaan's happy strand.\nRaging storms of strong temptation\nDrove me from my home astray:\nBear me, balmy southern breezes,\nTo its verdant shores away!\n\nSpite of waves and counter-currents\nRolling o'er me from each side,\nThrough the seas and storms opposing,\nI shall stem the swelling tide.\nThan the floods thy word is stronger,\nStronger than the 'whelming wave:\nAll my hope I calmly venture\nOn thy promise, Lord, to save.\n\nNot much longer must I battle\nWith the billows thus forlorn,\nLand is nigh, each faithful promise\nShews how nigh Salvation's morn.\nNot the deep shall be my dwelling:,\nJoyful shall my spirit come,\nWhen the seas have cleansed and proved me,\nTo my loved eternal Home.\n\nYea, methinks I catch already\nFragrant perfumes from the land,\nWafted by celestial breezes;\nSurely it is near at hand.\nO could I its coast discover,\nBlessed country free from strife;\nThere my dearest friends are dwelling,\nThere is everlasting life!","note":"A Welsh hymn of a traveler at sea catching the fragrance of the home shore; the translator credits Williams of Pantycelyn.","voice":"brian","source":{"name":"Favourite Welsh Hymns, translated by Joseph Morris (1854)","url":"https://www.gutenberg.org/ebooks/30370"},"rights":"pd","pd":"published 1854; Morris translated these in 1854"},{"id":"celtx-manx-christianity-came","title":"How Christianity Came to Man","by":"Traditional (Manx)","tr":"quoted by A. W. Moore","year":1891,"trad":["celtic","christian"],"denom":["manx"],"type":"poem","occasion":["blessing","funeral","gratitude"],"text":"Thus it was that Christianity first came to Man,\nBy St. Patrick planted in,\nAnd to establish Christ in us,\nAnd also in our children.\n\nHe then blessed Saint German,\nAnd left him a bishop in it,\nTo strengthen the faith more and more,\nAnd faithfully built chapels in it.\n\nFor each four quarterlands he made a chapel\nFor people of them to meet in prayer;\nHe also built German Church in Peel Castle,\nWhich remaineth there until this day.\n\nBefore German had finished his work,\nGod sent for him, and he died;\nAs ye yourselves know that this messenger\nCannot be put off by using means.\n\nHe died and his corpse was laid\nWhere a great bank had been, but soon was levelled;\nA cross of stone is set at his feet\nIn his own church in Peel Castle.\n\nThen came Maughold, we are told.\nAnd came on shore at the Head,\nAnd built a church and yard around.\nAt the place he thought to have his dwelling.\n\nThe chapels which Saint German ordered\nFor the people to come to prayers in them,\nMaughold put a parcel of them into one,\nAnd thus make regular parishes.\n\nMaughold died, and he is laid\nIn his own church at Maughold Head.\nAnd the next Bishop that came after\nTo the best of my knowledge was Lonnan.\n\nConnaghan then came next,\nAnd then Marown the third;\nThere all three lie in Marown,\nAnd there for ever lie unmolested.\n\nNow we will pass by these holy men,\nAnd commit their souls to the Son of God.\nIt profiteth them not to praise them more\nUntil they appear before the King of Kings.","note":"From the old Manx Traditionary Ballad: Patrick, German, Maughold, Lonan, and Marown remembered, their souls committed to the Son of God.","voice":"brian","source":{"name":"The Folk-lore of the Isle of Man, A. W. Moore (1891)","url":"https://archive.org/details/folkloreofisleof00moor/page/20/mode/1up"},"rights":"pd","pd":"published 1891; Moore died 1909"}];
